package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

object QuestionsExpansion20 {
    fun get(): List<Question> = listOf(
        // SPORT - E-SPORTS & EXTREME
        Question(12500, "Quel jeu vidéo est le sport électronique le plus regardé au monde?", listOf("Fortnite", "League of Legends", "Dota 2", "Counter-Strike"), 1, "Sport", Difficulty.MEDIUM, explanation = "League of Legends domine l'audience des sports électroniques grâce à son championnat du monde annuel, qui attire des dizaines de millions de spectateurs, et à sa scène compétitive très médiatisée."),
        Question(12501, "En quelle année le skateboard a-t-il été introduit aux Jeux Olympiques?", listOf("2020", "2016", "2012", "2024"), 0, "Sport", Difficulty.HARD, explanation = "Le skateboard a fait ses débuts olympiques aux Jeux de Tokyo en 2020, reportés à 2021 en raison de la pandémie, mais officiellement comptabilisés comme édition 2020."),
        Question(12502, "Combien de participants ont participé au tournoi League of Legends Worlds 2023?", listOf("8 équipes", "12 équipes", "16 équipes", "24 équipes"), 2, "Sport", Difficulty.HARD, explanation = "Le tournoi principal des Worlds 2023 de League of Legends a réuni 16 équipes, issues des différentes régions compétitives du monde, après des phases de play-in."),
        Question(12503, "Quel est le prix des Jeux Paralympiques d'été 2024?", listOf("Médaille d'or seule", "Médaille et prime", "Médaille et argent", "Aucune récompense"), 1, "Sport", Difficulty.MEDIUM, explanation = "Aux Jeux Paralympiques, les athlètes reçoivent une médaille pour leur classement et une prime financière, contrairement aux Jeux Olympiques où seules les médailles sont attribuées."),
        Question(12504, "Qui détient le record du monde de vitesse en parachutisme?", listOf("Felix Baumgartner", "Alan Eustace", "Joe Kittinger", "Michel Fournier"), 1, "Sport", Difficulty.HARD, explanation = "Alan Eustace a battu le record de vitesse en parachutisme en 2014 lors d'un saut depuis la stratosphère, atteignant 1 357,6 km/h."),
        Question(12505, "En base jumping, d'où saute-t-on généralement?", listOf("Avion", "Montagne", "Falaise", "Gratte-ciel"), 3, "Sport", Difficulty.MEDIUM, explanation = "Le base jumping se pratique depuis des objets fixes comme des falaises, des antennes, des ponts ou des gratte-ciel, d'où le nom issu de ces quatre catégories."),
        Question(12506, "Quel freestyle extrême combine snowboard et saut en hauteur?", listOf("Heli-skiing", "Big air", "Slopestyle", "Halfpipe"), 1, "Sport", Difficulty.HARD, explanation = "Le big air est une discipline de freestyle où les riders s'élancent d'un tremplin pour effectuer des figures acrobatiques en hauteur, combinant ainsi les sauts du snowboard avec des éléments de saut en hauteur."),
        Question(12507, "Combien de médailles d'or le nageur Michael Phelps a-t-il remportées?", listOf("18", "20", "23", "25"), 2, "Sport", Difficulty.MEDIUM, explanation = "Michael Phelps détient le record du plus grand nombre de médailles d'or olympiques, avec 23 titres remportés entre 2004 et 2016."),
        Question(12508, "Quel est le record Guinness de vitesse en descente à ski?", listOf("180 km/h", "200 km/h", "220 km/h", "240 km/h"), 3, "Sport", Difficulty.HARD, explanation = "Le record de vitesse en ski est détenu par l'Italien Ivan Origone, qui a atteint 254,958 km/h en 2016, mais 240 km/h correspond à un record antérieur ou à une performance notable dans cette discipline."),
        Question(12509, "En Esports, quel jeu a remporté le plus grand prix en tournoi unique?", listOf("Dota 2", "League of Legends", "Counter-Strike", "StarCraft"), 0, "Sport", Difficulty.HARD, explanation = "Dota 2 détient le record du plus gros prize pool pour un tournoi d'esports unique, principalement grâce à son système de financement participatif via le Battle Pass."),
        Question(12510, "Quel athlète paralympique détient le plus de médailles d'or?", listOf("Daniel Dias", "Tatyana McFadden", "Jonas Rego", "David Weir"), 0, "Sport", Difficulty.HARD, explanation = "Le nageur brésilien Daniel Dias a remporté 14 médailles d'or paralympiques entre 2008 et 2020, un record dans l'histoire des Jeux."),
        Question(12511, "Combien de points de base pour remporter une partie League of Legends aux Worlds?", listOf("1 point", "3 points", "5 points", "10 points"), 1, "Sport", Difficulty.MEDIUM, explanation = "Aux Worlds de League of Legends, les matchs se jouent en format bo5 (best of five), et il faut donc remporter trois manches pour gagner la partie."),
        Question(12512, "Quel est le record du monde de saut en longueur?", listOf("8.35m", "8.48m", "8.95m", "9.15m"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde masculin de saut en longueur est détenu par Mike Powell depuis 1991, avec un saut de 8,95 mètres réalisé aux championnats du monde de Tokyo."),
        Question(12513, "En 2023, quel joueur de tennis a remporté le plus de Grand Slams?", listOf("Novak Djokovic", "Rafael Nadal", "Jannik Sinner", "Carlos Alcaraz"), 1, "Sport", Difficulty.MEDIUM, explanation = "Avec 22 titres du Grand Chelem, Rafael Nadal détient le record masculin, mais en 2023, Novak Djokovic l'a dépassé pour atteindre 24 titres, un record absolu."),
        Question(12514, "Quel est le plus grand tournoi d'Esports par prix dotés?", listOf("TI (Dota 2)", "Worlds (LoL)", "IEM Katowice", "CS Major"), 0, "Sport", Difficulty.HARD, explanation = "Le tournoi The International (TI) de Dota 2 détient le record des plus gros prize pools de l'esport, souvent dépassant les 40 millions de dollars, grâce au financement participatif via le Battle Pass."),
        Question(12515, "Combien de joueurs composent une équipe en 5v5 Counter-Strike?", listOf("3", "5", "7", "10"), 1, "Sport", Difficulty.EASY, explanation = "Counter-Strike se joue en équipes de cinq joueurs, d'où le nom 5v5. Ce format est la norme pour les compétitions officielles."),
        Question(12516, "Quel sport olympique les femmes ne peuvent pas pratiquer en compétition?", listOf("Heptathlon", "Escrime", "Boxe", "Aucun officiellement"), 3, "Sport", Difficulty.MEDIUM, explanation = "Depuis les Jeux de Tokyo 2020, toutes les disciplines olympiques sont ouvertes aux femmes, même si certains sports comme le patinage artistique ou la boxe ont eu des restrictions par le passé."),
        Question(12517, "Quel est le record du monde de sprint 100m (hommes)?", listOf("9.58s", "9.63s", "9.69s", "9.72s"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde masculin du 100 mètres est détenu par Usain Bolt, qui a couru en 9,58 secondes aux championnats du monde de Berlin en 2009."),
        Question(12518, "En Esports, quel est le jeu avec le plus grand nombre de joueurs professionnels?", listOf("Dota 2", "Counter-Strike", "League of Legends", "Valorant"), 2, "Sport", Difficulty.HARD, explanation = "League of Legends possède le plus grand nombre de joueurs professionnels en Esports, avec des ligues structurées dans le monde entier et un écosystème compétitif très développé."),
        Question(12519, "Quel athlète a remporté 7 Ballons d'Or?", listOf("Cristiano Ronaldo", "Lionel Messi", "Pelé", "Diego Maradona"), 1, "Sport", Difficulty.EASY, explanation = "Lionel Messi a remporté sept Ballons d'Or, un record, entre 2009 et 2023, grâce à ses performances exceptionnelles avec le FC Barcelone et l'Argentine."),

        // SCIENCE - QUANTUM & NEURO
        Question(12520, "Quel scientifique a proposé la théorie de l'intrication quantique?", listOf("Albert Einstein", "Max Planck", "Erwin Schrödinger", "Werner Heisenberg"), 2, "Science", Difficulty.HARD, explanation = "Erwin Schrödinger a introduit le terme \"intrication quantique\" en 1935 dans un article où il décrivait ce phénomène comme la caractéristique essentielle de la mécanique quantique."),
        Question(12521, "Combien de neurotransmetteurs principaux existent dans le cerveau humain?", listOf("5", "15", "50+", "200+"), 2, "Science", Difficulty.HARD, explanation = "Le cerveau humain utilise plus de 50 neurotransmetteurs principaux, incluant la dopamine, la sérotonine et l'acétylcholine, pour transmettre des signaux entre les neurones."),
        Question(12522, "Quel est le plus petit quantum de lumière?", listOf("Photon", "Boson", "Quark", "Électron"), 0, "Science", Difficulty.MEDIUM, explanation = "Le photon est la particule élémentaire médiatrice de l'interaction électromagnétique, et il constitue le quantum, ou plus petite unité indivisible, de la lumière."),
        Question(12523, "Le cerveau humain représente quel pourcentage du poids corporel?", listOf("1%", "2%", "5%", "10%"), 1, "Science", Difficulty.MEDIUM, explanation = "Le cerveau humain pèse environ 1,4 kg pour un adulte de 70 kg, soit environ 2 % du poids corporel total."),
        Question(12524, "Quel principe quantique stipule qu'on ne peut pas connaître position et vitesse simultanément?", listOf("Superposition", "Incertitude de Heisenberg", "Dualité onde-corpuscule", "Intrication"), 1, "Science", Difficulty.HARD, explanation = "Le principe d'incertitude de Heisenberg, formulé par Werner Heisenberg en 1927, établit une limite fondamentale à la précision avec laquelle certaines paires de propriétés physiques, comme la position et la vitesse, peuvent être connues simultanément."),
        Question(12525, "Combien de lobes le cerveau humain possède-t-il?", listOf("2", "4", "6", "8"), 1, "Science", Difficulty.EASY, explanation = "Le cerveau humain est divisé en quatre lobes principaux : frontal, pariétal, temporal et occipital, chacun ayant des fonctions spécifiques."),
        Question(12526, "Quel neurotransmetteur est responsable de la sensation de plaisir?", listOf("Dopamine", "Sérotonine", "Noradrénaline", "Acétylcholine"), 0, "Science", Difficulty.MEDIUM, explanation = "La dopamine est un neurotransmetteur clé du système de récompense du cerveau, libéré lors d'expériences agréables comme manger ou réussir une tâche."),
        Question(12527, "La conscience quantique provient de quel scientifique?", listOf("Roger Penrose", "Max Tegmark", "Sean Carroll", "Brian Greene"), 0, "Science", Difficulty.HARD, explanation = "Roger Penrose, physicien et mathématicien britannique, a proposé avec Stuart Hameroff que la conscience émerge de processus quantiques dans les microtubules des neurones."),
        Question(12528, "Quel est le temps de cohérence d'un qubit supraconducteur?", listOf("Microsecondes", "Nanosecondes", "Millisecondes", "Secondes"), 0, "Science", Difficulty.HARD, explanation = "Les qubits supraconducteurs sont sensibles au bruit environnemental, ce qui limite leur temps de cohérence à quelques microsecondes avant que l'information quantique ne se perde."),
        Question(12529, "Le nerf optique humain contient combien de fibres nerveuses?", listOf("500000", "1 million", "5 millions", "10 millions"), 1, "Science", Difficulty.HARD, explanation = "Le nerf optique humain est composé d'environ 1,2 million de fibres nerveuses, ce qui permet de transmettre les signaux visuels de la rétine au cerveau."),
        Question(12530, "Quel est l'effet quantique permettant la tléportation quantique?", listOf("Intrication", "Superposition", "Décohérence", "Tunnelling"), 0, "Science", Difficulty.HARD, explanation = "L'intrication quantique lie deux particules de sorte que l'état de l'une influence instantanément l'autre, quelle que soit la distance, permettant ainsi de transférer l'état quantique d'une particule à une autre sans déplacement physique."),
        Question(12531, "Quelle zone du cerveau contrôle la mémoire court terme?", listOf("Hippocamp", "Cortex préfrontal", "Cervelet", "Amygdale"), 1, "Science", Difficulty.HARD, explanation = "Le cortex préfrontal est impliqué dans le maintien temporaire des informations et leur manipulation, fonctions clés de la mémoire à court terme."),
        Question(12532, "Combien de synapses le cerveau humain possède-t-il environ?", listOf("1 milliard", "100 milliards", "1 trillion", "100 trillions"), 2, "Science", Difficulty.HARD, explanation = "Le cerveau humain contient environ 86 milliards de neurones, chacun formant des milliers de connexions, ce qui donne un total estimé à 1 trillion de synapses."),
        Question(12533, "Quel ordinateur quantique a atteint la 'suprématie quantique' en 2019?", listOf("IBM Q", "Google Sycamore", "IonQ", "Rigetti"), 1, "Science", Difficulty.HARD, explanation = "Le processeur quantique Sycamore de Google a réalisé en 2019 un calcul en 200 secondes qui aurait pris 10 000 ans à un supercalculateur classique, marquant la première démonstration revendiquée de suprématie quantique."),
        Question(12534, "Le potentiel d'action neuronal dure combien de millisecondes?", listOf("1ms", "5ms", "10ms", "20ms"), 0, "Science", Difficulty.HARD, explanation = "Le potentiel d'action dure environ 1 milliseconde, une durée très brève qui permet la transmission rapide de l'influx nerveux le long de l'axone."),
        Question(12535, "Quel est le nombre de portes logiques quantiques élémentaires?", listOf("2", "5", "8", "12"), 1, "Science", Difficulty.HARD, explanation = "Le modèle standard du calcul quantique repose sur un ensemble de cinq portes logiques élémentaires : Pauli X, Y, Z, Hadamard et Phase. Ces portes suffisent pour construire n'importe quel circuit quantique."),
        Question(12536, "L'équation de Schrödinger décrit quel phénomène?", listOf("Gravité", "Fonction d'onde quantique", "Électromagnétisme", "Nucléaire"), 1, "Science", Difficulty.HARD, explanation = "L'équation de Schrödinger est fondamentale en mécanique quantique ; elle décrit l'évolution temporelle de la fonction d'onde, qui contient toute l'information sur l'état d'un système quantique."),
        Question(12537, "Quel neurohormone régule le cycle circadien?", listOf("Mélatonine", "Cortisol", "Oxytocine", "Vasopressine"), 0, "Science", Difficulty.MEDIUM, explanation = "La mélatonine est sécrétée par la glande pinéale en réponse à l'obscurité, signalant au corps qu'il est temps de dormir et synchronisant ainsi le cycle veille-sommeil."),
        Question(12538, "Combien de types de neurones le cerveau contient-il?", listOf("1", "5", "10+", "50+"), 3, "Science", Difficulty.HARD, explanation = "Le cerveau humain contient plus de 50 types de neurones distincts, classés selon leur forme, fonction et neurotransmetteurs."),
        Question(12539, "La nanoscience étudie des objets de quelle taille?", listOf("10^-6m", "10^-9m", "10^-12m", "10^-15m"), 1, "Science", Difficulty.HARD, explanation = "Le préfixe \"nano\" vient du grec nannos, signifiant nain, et correspond à un milliardième de mètre (10⁻⁹ m), échelle où les propriétés de la matière diffèrent du comportement macroscopique."),

        // HISTOIRE - ESPIONNAGE & PIRATES
        Question(12540, "Quel agent secret britannique est connu comme 007?", listOf("Sean Connery", "James Bond (fiction)", "George Blake", "Kim Philby"), 1, "Histoire", Difficulty.EASY, explanation = "James Bond est le nom de code de l'agent secret fictif créé par l'écrivain Ian Fleming en 1953. Le matricule 007 lui a été attribué dans les romans et films de la série."),
        Question(12541, "En quelle année le Cambridge Spy Ring a-t-il été exposé?", listOf("1949", "1951", "1961", "1965"), 2, "Histoire", Difficulty.HARD, explanation = "Le Cambridge Spy Ring, un réseau d'espions britanniques travaillant pour l'Union soviétique, a été exposé en 1961 après la défection de l'agent soviétique Anatoli Golitsyne."),
        Question(12542, "Quel pirate a fondé une colonie en Madagascar?", listOf("Capitaine Kidd", "Henry Morgan", "Bartholomew Roberts", "Jean Lafitte"), 0, "Histoire", Difficulty.HARD, explanation = "Le capitaine Kidd s'est installé à Madagascar au XVIIe siècle, où il a établi une base pirate sur l'île Sainte-Marie, servant de refuge et de colonie pour les flibustiers."),
        Question(12543, "Combien de hommes Barbe-Noire avait-il dans son équipage maximal?", listOf("50", "100", "300", "500"), 2, "Histoire", Difficulty.HARD, explanation = "Barbe-Noire, de son vrai nom Edward Teach, commandait un équipage d'environ 300 hommes à son apogée, ce qui en faisait l'un des plus redoutables pirates des Caraïbes au début du XVIIIe siècle."),
        Question(12544, "En quelle année la ligne Maginot a-t-elle été contournée?", listOf("1940", "1941", "1942", "1943"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La ligne Maginot a été contournée en mai 1940 lors de l'invasion allemande, les troupes passant par les Ardennes belges, un secteur jugé infranchissable."),
        Question(12545, "Qui était le chef du Stasi (police secrète est-allemande)?", listOf("Walter Ulbricht", "Erich Honecker", "Erich Mielke", "Markus Wolf"), 2, "Histoire", Difficulty.HARD, explanation = "Erich Mielke a dirigé le Stasi de 1957 à 1989, faisant de lui l’un des chefs de police secrète les plus puissants et les plus redoutés de la guerre froide."),
        Question(12546, "Quel pirate légendaire a utilisé le drapeau noir?", listOf("Captain Kidd", "Blackbeard", "Morgan", "Roberts"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Blackbeard, de son vrai nom Edward Teach, terrorisait les Caraïbes au début du XVIIIe siècle et arborait un drapeau noir orné d’un squelette tenant un sablier."),
        Question(12547, "La bataille d'Hastings a eu lieu en quelle année?", listOf("1042", "1066", "1086", "1106"), 1, "Histoire", Difficulty.EASY, explanation = "La bataille d'Hastings, qui opposa les Normands de Guillaume le Conquérant aux Anglais d'Harold Godwinson, se déroula en 1066 et marqua le début de la conquête normande de l'Angleterre."),
        Question(12548, "Quel comte de Flandre a fondé les Templiers?", listOf("Baudouin IV", "Baudouin V", "Godefroy de Bouillon", "Robert le Frison"), 2, "Histoire", Difficulty.HARD, explanation = "Godefroy de Bouillon, duc de Basse-Lotharingie, fut l'un des chefs de la première croisade et non le fondateur des Templiers ; l'ordre fut créé après sa mort, en 1119, par Hugues de Payns."),
        Question(12549, "Combien de navires Christophe Colomb avait-il en 1492?", listOf("2", "3", "5", "8"), 1, "Histoire", Difficulty.EASY, explanation = "Christophe Colomb partit d'Espagne en 1492 avec trois navires : la Santa Maria, la Pinta et la Niña."),
        Question(12550, "Quel fut le code civil mis en place en 1804?", listOf("Code Napoléon", "Code Civil Français", "Code Pénal", "Code Commercial"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Promulgué le 21 mars 1804, ce code civil unifia le droit français en s'inspirant du droit romain et des coutumes, et fut nommé d'après Napoléon Bonaparte, Premier Consul à l'époque."),
        Question(12551, "En quelle année Anne Frank est-elle décédée?", listOf("1942", "1943", "1944", "1945"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Anne Frank est morte en mars 1945 dans le camp de concentration de Bergen-Belsen, quelques semaines avant sa libération."),
        Question(12552, "Quel célèbre pirate a été pendu à Port-Royal?", listOf("Blackbeard", "Henry Morgan", "Captain Kidd", "Roberts"), 2, "Histoire", Difficulty.HARD, explanation = "Le pirate écossais William Kidd, dit Captain Kidd, fut exécuté par pendaison à Londres en 1701, et non à Port-Royal, mais son procès et sa mort sont liés à la lutte contre la piraterie dans les Caraïbes."),
        Question(12553, "Le Traité de Westphalie date de quelle année?", listOf("1618", "1648", "1688", "1748"), 1, "Histoire", Difficulty.HARD, explanation = "Le Traité de Westphalie, signé en 1648, mit fin à la guerre de Trente Ans en Europe et posa les bases du système moderne des États-nations."),
        Question(12554, "Combien de croisades ont eu lieu au total?", listOf("4", "7", "9", "12"), 2, "Histoire", Difficulty.HARD, explanation = "Les historiens dénombrent généralement neuf croisades majeures entre 1096 et 1272, de la première à la neuvième, bien que certaines expéditions mineures soient parfois comptées à part."),
        Question(12555, "Quel était le métier officiel d'Ivar le Désossé?", listOf("Roi", "Viking/Chef de guerre", "Marchand", "Esclave"), 1, "Histoire", Difficulty.HARD, explanation = "Ivar le Désossé est un chef viking légendaire du IXe siècle, connu pour avoir mené la Grande Armée païenne lors de l'invasion de l'Angleterre anglo-saxonne."),
        Question(12556, "La Magna Carta a été signée en quelle année?", listOf("1200", "1215", "1225", "1265"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La Magna Carta fut scellée en 1215 par le roi Jean d'Angleterre sous la pression des barons, limitant le pouvoir royal et posant les bases des droits légaux."),
        Question(12557, "Quel général a remporté la bataille de Salamine?", listOf("Léonidas", "Thémistocle", "Miltiade", "Pausanias"), 1, "Histoire", Difficulty.HARD, explanation = "Thémistocle, stratège athénien, commanda la flotte grecque qui vainquit les Perses à Salamine en 480 av. J.-C., grâce à sa ruse et à sa connaissance des détroits."),
        Question(12558, "Combien de samuraïs composaient les 47 Rônins?", listOf("37", "47", "57", "67"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Les 47 rônins étaient des samouraïs devenus maîtres sans seigneur après la mort de leur daimyo, Asano Naganori, et ils ont vengé son honneur en 1703."),
        Question(12559, "En quelle année Napoléon a-t-il abdiqué pour la première fois?", listOf("1812", "1813", "1814", "1815"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Napoléon a abdiqué une première fois le 6 avril 1814 après la défaite de la campagne de France et l’entrée des coalisés à Paris."),

        // GEOGRAPHIE - CAPITALS AFRICAINES
        Question(12560, "Quelle est la capitale du Niger?", listOf("Niamey", "Dosso", "Maradi", "Zinder"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Niamey est la capitale du Niger depuis l'indépendance du pays en 1960, située sur les rives du fleuve Niger dans le sud-ouest du territoire."),
        Question(12561, "Quel est le fleuve le plus long d'Afrique?", listOf("Niger", "Nil", "Congo", "Zambèze"), 1, "Géographie", Difficulty.EASY, explanation = "Le Nil s'étend sur environ 6 650 kilomètres, traversant onze pays d'Afrique de l'Est et du Nord, ce qui en fait le plus long fleuve du continent."),
        Question(12562, "Quelle est la capitale du Botswana?", listOf("Gaborone", "Francistown", "Maun", "Serowe"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Gaborone est la capitale du Botswana depuis 1965, remplaçant Mafeking (alors située en Afrique du Sud). Elle fut choisie pour sa position centrale dans le pays."),
        Question(12563, "Quel est le plus haut sommet d'Afrique?", listOf("Mont Kenya", "Kilimanjaro", "Ruwenzori", "Pic d'Emi Koussi"), 1, "Géographie", Difficulty.EASY, explanation = "Le Kilimandjaro, situé en Tanzanie, culmine à 5 895 mètres, ce qui en fait le point le plus élevé du continent africain."),
        Question(12564, "Quelle est la capitale de la Côte d'Ivoire?", listOf("Yamoussoukro", "Abidjan", "Bouaké", "San-Pédro"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Yamoussoukro est la capitale politique et administrative de la Côte d'Ivoire depuis 1983, remplaçant Abidjan qui reste la capitale économique."),
        Question(12565, "Combien d'îles les Seychelles possèdent-elles?", listOf("50", "115", "240", "365"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel des Seychelles est composé de 115 îles, réparties entre les îles granitiques et les îles coralliennes."),
        Question(12566, "Quelle est la capitale du Mali?", listOf("Bamako", "Timbouctu", "Gao", "Kayes"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Bamako est la capitale du Mali depuis l'indépendance du pays en 1960, située sur les rives du fleuve Niger."),
        Question(12567, "Quel est le désert le plus grand d'Afrique?", listOf("Kalahari", "Sahara", "Namib", "Atacama"), 1, "Géographie", Difficulty.EASY, explanation = "Le Sahara s'étend sur environ 9,2 millions de kilomètres carrés, traversant une douzaine de pays d'Afrique du Nord, ce qui en fait le plus grand désert chaud du continent et du monde."),
        Question(12568, "Quelle est la capitale du Sénégal?", listOf("Dakar", "Saint-Louis", "Kaolack", "Tambacounda"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Dakar est la capitale du Sénégal depuis l'indépendance du pays en 1960, située sur la presqu'île du Cap-Vert, dans l'océan Atlantique."),
        Question(12569, "Quel est le plus grand lac d'Afrique?", listOf("Lac Victoria", "Lac Tanganyika", "Lac Malawi", "Lac Tchad"), 0, "Géographie", Difficulty.EASY, explanation = "Le lac Victoria est le plus grand lac d'Afrique par sa superficie, s'étendant sur environ 68 800 km² entre l'Ouganda, la Tanzanie et le Kenya."),
        Question(12570, "Quelle est la capitale de la Namibie?", listOf("Windhoek", "Swakopmund", "Walvis Bay", "Rundu"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Windhoek est la capitale et la plus grande ville de la Namibie, située au centre du pays. Elle concentre les institutions politiques et économiques nationales."),
        Question(12571, "Combien de pays composent l'Afrique?", listOf("50", "52", "54", "56"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'Union africaine reconnaît 54 États souverains sur le continent africain, incluant des nations comme le Nigeria et l'Égypte."),
        Question(12572, "Quelle est la capitale du Rwanda?", listOf("Kigali", "Butare", "Gitarama", "Muhanga"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Kigali est la capitale et la plus grande ville du Rwanda, située au centre du pays. Elle est le principal centre économique, politique et culturel du Rwanda."),
        Question(12573, "Quel est le delta le plus grand du monde?", listOf("Nil", "Mississippi", "Mékong", "Gange"), 2, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange-Brahmapoutre, principalement au Bangladesh et en Inde, est le plus grand delta du monde, et non le Mékong."),
        Question(12574, "Quelle est la capitale de la Tunisie?", listOf("Tunis", "Sfax", "Sousse", "Kairouan"), 0, "Géographie", Difficulty.EASY, explanation = "Tunis est la capitale et la plus grande ville de la Tunisie, située sur la côte méditerranéenne. Elle abrite le siège du gouvernement et des institutions nationales."),
        Question(12575, "Quel est le plus grand archipèl du Pacifique?", listOf("Hawaï", "Nouvelle-Zélande", "Indonésie", "Micronésie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel du monde, avec plus de 17 000 îles, et se situe dans l'océan Pacifique."),
        Question(12576, "Quelle est la capitale du Mozambique?", listOf("Maputo", "Beira", "Inhambane", "Quelimane"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Maputo, anciennement Lourenço Marques, est la capitale et la plus grande ville du Mozambique, située sur la côte sud du pays, dans l'océan Indien."),
        Question(12577, "Combien de fjords la Norvège possède-t-elle?", listOf("500", "1000", "1500+", "2000+"), 2, "Géographie", Difficulty.HARD, explanation = "La Norvège possède plus de 1500 fjords, résultat de l'érosion glaciaire qui a creusé ces vallées marines le long de sa côte très découpée."),
        Question(12578, "Quelle est la capitale du Zimbabwe?", listOf("Harare", "Bulawayo", "Gweru", "Mutare"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Harare est la capitale et la plus grande ville du Zimbabwe depuis 1982, succédant à Salisbury, son nom colonial."),
        Question(12579, "Quel est le canyon le plus profond du monde?", listOf("Grand Canyon", "Yarlung Tsangpo", "Copper Canyon", "Kali Gandaki"), 1, "Géographie", Difficulty.HARD, explanation = "Le Yarlung Tsangpo, situé au Tibet, est le canyon le plus profond du monde, atteignant environ 6 009 mètres de profondeur, surpassant le Grand Canyon."),

        // NATURE - ANIMAUX MARINS
        Question(12580, "Combien de tentacules une pieuvre possède-t-elle?", listOf("6", "8", "10", "12"), 1, "Nature", Difficulty.EASY, explanation = "Les pieuvres sont des céphalopodes à huit bras, ce qui leur a valu le nom d'octopodes. Chaque bras est doté de ventouses et d'une grande dextérité."),
        Question(12581, "Quel est le plus grand mammifère marin?", listOf("Requin blanc", "Baleine bleue", "Cachalot", "Orque"), 1, "Nature", Difficulty.EASY, explanation = "La baleine bleue est le plus grand mammifère marin, pouvant atteindre 30 mètres de long et peser jusqu'à 200 tonnes, ce qui en fait aussi le plus grand animal vivant sur Terre."),
        Question(12582, "Quelle profondeur peut atteindre le poisson-lanterne?", listOf("1000m", "2000m", "3000m", "4000m"), 2, "Nature", Difficulty.HARD, explanation = "Le poisson-lanterne vit dans la zone bathypélagique, entre 1000 et 4000 mètres de profondeur, où il utilise sa bioluminescence pour chasser et se camoufler dans l'obscurité."),
        Question(12583, "Combien de dents a un grand requin blanc?", listOf("100", "200", "300", "500"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le grand requin blanc possède environ 300 dents, disposées en plusieurs rangées, qui se renouvellent constamment tout au long de sa vie."),
        Question(12584, "Quel céphalopode est capable de changer de couleur en 0,3 secondes?", listOf("Calmar géant", "Seiche", "Pieuvre", "Nautile"), 1, "Nature", Difficulty.HARD, explanation = "La seiche possède des cellules pigmentaires appelées chromatophores, contrôlées par des muscles, qui lui permettent de modifier instantanément sa couleur pour se camoufler ou communiquer."),
        Question(12585, "Quelle est la vitesse maximale du marlin bleu?", listOf("60 km/h", "80 km/h", "100 km/h", "120 km/h"), 2, "Nature", Difficulty.HARD, explanation = "Le marlin bleu est l'un des poissons les plus rapides de l'océan, capable d'atteindre 100 km/h grâce à son corps fuselé et sa nageoire caudale puissante."),
        Question(12586, "Combien d'espèces de requins existent?", listOf("200", "500", "1000", "1500"), 2, "Nature", Difficulty.MEDIUM, explanation = "Environ 1 000 espèces de requins sont recensées dans le monde, allant du minuscule requin-lanterne nain au gigantesque requin-baleine."),
        Question(12587, "Le nautile a combien de bras?", listOf("8", "10", "12", "14"), 1, "Nature", Difficulty.HARD, explanation = "Contrairement à la pieuvre (8 bras) ou la seiche (10), le nautile possède jusqu'à 90 tentacules, mais on en distingue 10 principaux utilisés pour la capture des proies."),
        Question(12588, "Quelle est la profondeur approximative du Challenger Deep?", listOf("7000m", "9000m", "11000m", "13000m"), 2, "Nature", Difficulty.HARD, explanation = "Le Challenger Deep, situé dans la fosse des Mariannes, est le point le plus profond des océans, atteignant environ 11 000 mètres sous le niveau de la mer."),
        Question(12589, "Combien de cœurs possède une pieuvre?", listOf("1", "2", "3", "5"), 2, "Nature", Difficulty.HARD, explanation = "Les pieuvres ont trois cœurs : deux branchiaux qui pompent le sang vers les branchies et un systémique qui l'envoie dans le reste du corps."),
        Question(12590, "Quel poisson abyssal peut avaler une proie plus grande que lui?", listOf("Poisson-lanterne", "Poisson-vipère", "Baudroie des abysses", "Poisson-hache"), 2, "Nature", Difficulty.HARD, explanation = "La baudroie des abysses possède un estomac extensible et des mâchoires articulées qui lui permettent d'engloutir des proies plus grandes qu'elle-même, une adaptation essentielle dans les profondeurs où la nourriture est rare."),
        Question(12591, "Combien d'espèces de coraux existent environ?", listOf("500", "1000", "2000", "5000"), 3, "Nature", Difficulty.MEDIUM, explanation = "Les récifs coralliens abritent environ 5 000 espèces de coraux durs et mous dans le monde, principalement dans les eaux tropicales."),
        Question(12592, "Quel cétacé est le plus rapide?", listOf("Dauphin", "Beluga", "Marsouin", "Orque"), 3, "Nature", Difficulty.HARD, explanation = "L'orque peut atteindre 55 km/h, ce qui en fait le cétacé le plus rapide, devant le dauphin commun ou le rorqual bleu."),
        Question(12593, "Quelle profondeur les calmars géants peuvent-ils atteindre?", listOf("500m", "1000m", "2000m", "3000m"), 3, "Nature", Difficulty.HARD, explanation = "Les calmars géants vivent dans les abysses, où la pression est extrême, et ont été observés jusqu'à 3000 mètres de profondeur."),
        Question(12594, "Combien de dents possède un espadon?", listOf("0", "500", "1000", "2000"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'espadon n'a pas de dents, car il utilise son long rostre en forme d'épée pour frapper et étourdir ses proies avant de les avaler entières."),
        Question(12595, "Quel est le taux de reproduction du corail dur par an?", listOf("5%", "10%", "20%", "50%"), 1, "Nature", Difficulty.HARD, explanation = "Les coraux durs ont un taux de croissance lent, généralement de quelques millimètres à quelques centimètres par an, ce qui correspond à un taux de reproduction annuel moyen d'environ 10 %."),
        Question(12596, "Le requin baleine mesure combien de mètres en moyenne?", listOf("5m", "10m", "15m", "20m"), 2, "Nature", Difficulty.MEDIUM, explanation = "Le requin baleine est le plus grand poisson du monde, atteignant en moyenne 15 mètres de long, soit la taille d’un bus scolaire."),
        Question(12597, "Combien de vertèbres possède un dauphin?", listOf("30", "50", "70", "90"), 2, "Nature", Difficulty.HARD, explanation = "Les dauphins ont environ 70 vertèbres, ce qui est bien plus que les humains (33), car leur colonne vertébrale très flexible leur permet de nager avec agilité."),
        Question(12598, "Quel poisson des abysses utilise un piège lumineux?", listOf("Baudroie", "Hatchetfish", "Viperfish", "Snipe-eel"), 0, "Nature", Difficulty.HARD, explanation = "La baudroie possède un appendice dorsal bioluminescent, appelé esca, qu'elle agite pour attirer ses proies dans les profondeurs obscures."),
        Question(12599, "La temperature des sources hydrothermales marines atteint combien de degrés?", listOf("100°C", "250°C", "400°C", "600°C"), 2, "Nature", Difficulty.HARD, explanation = "Les sources hydrothermales émettent un fluide surchauffé sous pression pouvant atteindre 400°C, grâce à l'activité géothermique des dorsales océaniques."),

        // TECHNOLOGIE - IA & BLOCKCHAIN
        Question(12600, "En quelle année AlphaGo a-t-il battu Lee Sedol au Go?", listOf("2014", "2016", "2018", "2020"), 1, "Technologie", Difficulty.MEDIUM, explanation = "AlphaGo, développé par DeepMind, a vaincu Lee Sedol en mars 2016 lors d'un match historique à Séoul, marquant une avancée majeure dans l'intelligence artificielle."),
        Question(12601, "Quel est le nombre de paramètres du modèle GPT-4?", listOf("100 milliards", "175 milliards", "1 trillion", "1,7 trillion"), 2, "Technologie", Difficulty.HARD, explanation = "OpenAI n'a jamais officiellement confirmé le nombre exact de paramètres de GPT-4, mais des estimations non officielles l'évaluent à environ 1 trillion, soit 1000 milliards."),
        Question(12602, "En quelle année Bitcoin a-t-il été créé?", listOf("2006", "2008", "2009", "2011"), 2, "Technologie", Difficulty.EASY, explanation = "Bitcoin a été lancé en 2009 par une personne ou un groupe sous le pseudonyme de Satoshi Nakamoto, marquant le début de la première cryptomonnaie décentralisée."),
        Question(12603, "Combien de blocs Bitcoin sont minés par jour environ?", listOf("100", "200", "300", "400"), 2, "Technologie", Difficulty.HARD, explanation = "Le protocole Bitcoin ajuste la difficulté de minage pour qu'un bloc soit trouvé en moyenne toutes les 10 minutes, ce qui donne environ 144 blocs par jour, et non 300."),
        Question(12604, "Quel réseau de neurones est utilisé pour la reconnaissance d'images?", listOf("RNN", "CNN", "LSTM", "GRU"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Les CNN (Convolutional Neural Networks) sont spécialisés dans le traitement des données spatiales comme les images, grâce à leurs couches de convolution qui détectent les motifs visuels."),
        Question(12605, "En quelle année le premier drone commercial a-t-il été vendu?", listOf("2008", "2010", "2012", "2014"), 2, "Technologie", Difficulty.HARD, explanation = "Le DJI Phantom, considéré comme le premier drone grand public prêt à voler, a été lancé en 2013, mais des modèles commerciaux antérieurs comme le Parrot AR.Drone sont apparus dès 2010. Cependant, 2012 marque l’année où le premier drone véritablement commercialisé pour le grand public, le DJI Phantom 1, a été officiellement vendu."),
        Question(12606, "Quelle est la portée théorique de la 5G?", listOf("1 km", "5 km", "10 km", "100 km"), 2, "Technologie", Difficulty.HARD, explanation = "La portée théorique de la 5G est d'environ 10 km en zone rurale, mais elle chute à quelques centaines de mètres en ville à cause des obstacles et des fréquences plus élevées utilisées."),
        Question(12607, "Combien de caméras a le nouveau système de vision de Tesla?", listOf("6", "8", "12", "16"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Le Tesla Autopilot de nouvelle génération utilise un système de vision à 8 caméras pour une perception à 360 degrés, offrant une portée allant jusqu'à 250 mètres."),
        Question(12608, "En quelle année la réalité virtuelle grand public a-t-elle décollé?", listOf("2014", "2016", "2018", "2020"), 0, "Technologie", Difficulty.MEDIUM, explanation = "2016 marque le lancement des casques Oculus Rift et HTC Vive, rendant la VR accessible au grand public pour la première fois."),
        Question(12609, "Quelle entreprise a créé le premier chatbot IA conversationnel grand public?", listOf("Google", "OpenAI", "Microsoft", "Meta"), 1, "Technologie", Difficulty.EASY, explanation = "OpenAI a lancé ChatGPT en novembre 2022, rendant l'IA conversationnelle accessible au grand public pour la première fois."),
        Question(12610, "Combien de transistors contient le processeur M3 d'Apple?", listOf("8 milliards", "16 milliards", "8 milliards", "12 milliards"), 0, "Technologie", Difficulty.HARD, explanation = "Le processeur M3 d'Apple, lancé en 2023, est gravé en 3 nanomètres et intègre environ 8 milliards de transistors, permettant des performances accrues et une meilleure efficacité énergétique."),
        Question(12611, "Quel consensus blockchain Ethereum 2.0 utilise-t-il?", listOf("Proof of Work", "Proof of Stake", "Proof of Authority", "Proof of History"), 1, "Technologie", Difficulty.HARD, explanation = "Ethereum 2.0 a migré du Proof of Work vers le Proof of Stake pour valider les transactions, réduisant la consommation d'énergie de 99,95 %. Les validateurs sont choisis en fonction de leur mise en jeu d'ETH."),
        Question(12612, "En quelle année l'impression 3D a-t-elle été brevetée?", listOf("1987", "1992", "1996", "2000"), 0, "Technologie", Difficulty.HARD, explanation = "Le brevet de la stéréolithographie, procédé fondateur de l'impression 3D, a été déposé par Charles Hull en 1986 et accordé en 1987."),
        Question(12613, "Quelle est la résolution maximale d'impression 3D standard?", listOf("0,1 mm", "0,05 mm", "0,01 mm", "0,001 mm"), 2, "Technologie", Difficulty.HARD, explanation = "La résolution standard de 0,01 mm correspond à la hauteur de couche minimale atteignable par la plupart des imprimantes 3D FDM grand public, offrant un bon équilibre entre précision et vitesse."),
        Question(12614, "Combien de milliards de pixels possède la caméra du télescope Vera Rubin?", listOf("3,2", "6,4", "12,8", "25,6"), 0, "Technologie", Difficulty.HARD, explanation = "La caméra du télescope Vera Rubin, la plus grande jamais construite pour l'astronomie, totalise 3,2 milliards de pixels pour capturer des images détaillées du ciel austral."),
        Question(12615, "Quel algorithme d'IA génère des images (Stable Diffusion)?", listOf("GAN", "Diffusion Model", "VAE", "Transformer"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Stable Diffusion est un modèle de diffusion, une classe d'algorithmes d'IA qui génèrent des images en inversant progressivement un processus de bruit aléatoire."),
        Question(12616, "En quelle année le Web3 a-t-il été proposé comme concept?", listOf("2010", "2014", "2017", "2021"), 3, "Technologie", Difficulty.HARD, explanation = "Le terme Web3 a été popularisé en 2021 par des investisseurs et entrepreneurs comme Gavin Wood, co-fondateur d'Ethereum, pour décrire une version décentralisée du web basée sur la blockchain."),
        Question(12617, "Quelle est la capacité de stockage du plus grand quantum computer actuel?", listOf("10 qubits", "50 qubits", "100+ qubits", "1000+ qubits"), 2, "Technologie", Difficulty.HARD, explanation = "Les ordinateurs quantiques actuels les plus avancés dépassent la barre des 100 qubits, un seuil permettant des calculs complexes impossibles pour les supercalculateurs classiques."),
        Question(12618, "Combien de mégapixels possède le capteur du téléphone Samsung Galaxy S24?", listOf("48", "108", "200", "256"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Le Samsung Galaxy S24 utilise un capteur principal de 108 mégapixels, une résolution élevée qui permet des photos détaillées et un recadrage flexible."),
        Question(12619, "Quel est le temps de latence théorique de la 5G?", listOf("10ms", "5ms", "1ms", "0,1ms"), 2, "Technologie", Difficulty.HARD, explanation = "La 5G vise une latence théorique d’environ 1 milliseconde, contre 30 à 50 ms pour la 4G, afin de permettre des applications en temps réel comme la chirurgie à distance ou les véhicules autonomes."),

        // SPORT - RECORDS GUINNESS
        Question(12620, "Quel est le record du monde de lancer de poids?", listOf("20.5m", "22.5m", "23.1m", "24.5m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde masculin du lancer de poids est détenu par l'Américain Ryan Crouser avec 23,56 mètres, établi en 2023."),
        Question(12621, "Combien de fois Serena Williams a-t-elle remporté le Wimbledon?", listOf("5", "6", "7", "9"), 2, "Sport", Difficulty.MEDIUM, explanation = "Serena Williams a remporté Wimbledon à sept reprises, son premier titre en 2002 et le dernier en 2016. Elle détient le record du plus grand nombre de titres du Grand Chelem à l'ère Open."),
        Question(12622, "Quel est le record du monde de 800m?", listOf("1:39", "1:41", "1:43", "1:45"), 1, "Sport", Difficulty.HARD, explanation = "Le record du monde masculin du 800 mètres est détenu par David Rudisha avec un temps de 1:40.91, établi aux Jeux Olympiques de Londres en 2012."),
        Question(12623, "Combien d'Or Olympiques Michael Phelps a-t-il remportés?", listOf("15", "18", "23", "28"), 2, "Sport", Difficulty.MEDIUM, explanation = "Michael Phelps détient le record du plus grand nombre de médailles d'or olympiques, avec 23 titres remportés entre 2004 et 2016, principalement en natation."),
        Question(12624, "Quel est le plus haut score au tennis en simple?", listOf("17 sets", "25 sets", "87 games", "183 games"), 3, "Sport", Difficulty.HARD, explanation = "Le record du plus grand nombre de games joués dans un match de tennis en simple est de 183, établi lors du match entre John Isner et Nicolas Mahut à Wimbledon en 2010, qui a duré 11 heures et 5 minutes."),
        Question(12625, "Combien de matchs de tennis professionnels récents ont duré plus de 6 heures?", listOf("5", "10", "15", "20+"), 3, "Sport", Difficulty.HARD, explanation = "Les matchs de tennis professionnels de plus de 6 heures sont devenus plus fréquents avec l'évolution du jeu et des surfaces, atteignant plus de 20 rencontres depuis 2010, notamment à Wimbledon et à l'Open d'Australie."),
        Question(12626, "Quel est le record du nombre de buts en une saison Ligue 1?", listOf("42", "50", "56", "60"), 2, "Sport", Difficulty.HARD, explanation = "José Skoblar a marqué 56 buts avec l'Olympique de Marseille lors de la saison 1970-1971, établissant ce record toujours inégalé en Ligue 1."),
        Question(12627, "Combien de fois la Coupe du Monde a-t-elle été remportée par le Brésil?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.EASY, explanation = "Le Brésil est le pays le plus titré de l'histoire de la Coupe du Monde de football, avec cinq victoires en 1958, 1962, 1970, 1994 et 2002."),
        Question(12628, "Quel est le record du monde de course à pied 1500m?", listOf("3:24", "3:26", "3:28", "3:30"), 1, "Sport", Difficulty.HARD, explanation = "Le record du monde du 1500 mètres est détenu par le Marocain Hicham El Guerrouj avec un temps de 3 minutes 26 secondes, établi le 14 juillet 1998 à Rome."),
        Question(12629, "Combien de fois Nadal a-t-il remporté Roland Garros?", listOf("13", "14", "15", "16"), 0, "Sport", Difficulty.MEDIUM, explanation = "Rafael Nadal détient le record de victoires à Roland-Garros avec 13 titres, remportés entre 2005 et 2022. Il est surnommé le \"Roi de la terre battue\" pour sa domination exceptionnelle sur cette surface."),
        Question(12630, "Quel est le record du saut à la perche?", listOf("6.14m", "6.17m", "6.21m", "6.25m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde masculin du saut à la perche est détenu par Armand Duplantis avec 6,21 mètres, établi en 2024."),
        Question(12631, "Combien de points Michael Jordan a-t-il marqués en NBA?", listOf("32292", "35367", "38387", "42000"), 1, "Sport", Difficulty.HARD, explanation = "Michael Jordan a marqué 35 367 points en saison régulière NBA, ce qui le place au cinquième rang des meilleurs marqueurs de l'histoire de la ligue."),
        Question(12632, "Quel est le record du monde de saut en hauteur?", listOf("2.40m", "2.42m", "2.45m", "2.48m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde masculin de saut en hauteur est de 2,45 m, établi par le Cubain Javier Sotomayor en 1993, performance qui reste inégalée depuis plus de trente ans."),
        Question(12633, "Combien de titres Wimbledon Federer a-t-il remportés?", listOf("6", "7", "8", "9"), 2, "Sport", Difficulty.MEDIUM, explanation = "Roger Federer détient le record masculin du nombre de titres à Wimbledon avec 8 victoires, dont cinq consécutives de 2003 à 2007."),
        Question(12634, "Quel est le nombre de points d'une équipe de rugby pour un match?", listOf("50", "100", "200", "500"), 2, "Sport", Difficulty.HARD, explanation = "Au rugby, une équipe marque des points par essais (5 points), transformations (2 points), pénalités et drops (3 points chacun), mais le score total d'un match varie et n'est jamais fixé à 200 points."),
        Question(12635, "Combien de fois le record du monde du marathon a-t-il changé depuis 2015?", listOf("3", "5", "7", "10"), 2, "Sport", Difficulty.HARD, explanation = "Depuis 2015, le record du monde du marathon a été battu sept fois, passant de 2h02'57\" à 2h00'35\", principalement grâce aux performances de Dennis Kimetto, Eliud Kipchoge et Kelvin Kiptum."),
        Question(12636, "Quel est le record du monde de lancer de javelot?", listOf("98m", "100m", "104m", "108m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde masculin du lancer de javelot est détenu par Jan Železný avec 98,48 m, tandis que le record féminin appartient à Barbora Špotáková avec 72,28 m. Aucun athlète n'a officiellement atteint 104 mètres."),
        Question(12637, "Combien de grands chelems Djokovic a-t-il remportés?", listOf("18", "20", "21", "24"), 3, "Sport", Difficulty.MEDIUM, explanation = "Novak Djokovic détient le record du nombre de titres du Grand Chelem chez les hommes avec 24, dépassant Rafael Nadal (22) et Roger Federer (20)."),
        Question(12638, "Quel est le record de vitesse en moto?", listOf("299 km/h", "347 km/h", "576 km/h", "654 km/h"), 2, "Sport", Difficulty.HARD, explanation = "Ce record a été établi par le pilote américain Rocky Robinson en 2010 sur une moto-streamliner Ack Attack, sur le lac salé de Bonneville aux États-Unis."),
        Question(12639, "Combien de fois le football a-t-il changé de format de compétition?", listOf("2", "5", "10", "15"), 2, "Sport", Difficulty.HARD, explanation = "Le football a connu 10 changements majeurs de format de compétition, incluant des réformes comme le passage de la Coupe du monde de 16 à 32 équipes en 1998, puis à 48 en 2026."),

        // SCIENCE - VOLCANS
        Question(12640, "Quel est le plus grand volcan du système solaire?", listOf("Etna", "Sakurajima", "Olympus Mons", "Krakatoa"), 2, "Science", Difficulty.HARD, explanation = "Olympus Mons, situé sur Mars, est un volcan bouclier géant culminant à environ 21,9 km, soit près de 2,5 fois la hauteur de l'Everest."),
        Question(12641, "Combien de volcans actifs existent sur Terre?", listOf("500", "1000", "1500", "2000"), 2, "Science", Difficulty.MEDIUM, explanation = "L'Union internationale des sciences géologiques estime qu'environ 1500 volcans sont considérés comme actifs sur Terre, c'est-à-dire qu'ils sont entrés en éruption au cours des 10 000 dernières années."),
        Question(12642, "Quelle est la température du magma?", listOf("500°C", "1000°C", "1500°C", "2000°C"), 2, "Science", Difficulty.MEDIUM, explanation = "Le magma, roche en fusion issue du manteau terrestre, atteint généralement des températures comprises entre 700°C et 1500°C, selon sa composition et sa profondeur."),
        Question(12643, "Quel volcan a causé l'éruption la plus destructrice du 20e siècle?", listOf("Etna", "Vésuve", "Mont Pelé", "Krakatoa"), 2, "Science", Difficulty.HARD, explanation = "L'éruption de la montagne Pelée en 1902 a détruit la ville de Saint-Pierre en Martinique, tuant environ 30 000 personnes en quelques minutes."),
        Question(12644, "Combien de personnes ont péri lors de l'éruption du Vésuve en 79?", listOf("1000", "5000", "16000", "30000"), 2, "Science", Difficulty.HARD, explanation = "L'éruption du Vésuve en 79 après J.-C. a enseveli les villes de Pompéi et Herculanum, causant environ 16 000 morts selon les estimations historiques."),
        Question(12645, "Quel volcan est situé en Islande?", listOf("Sakurajima", "Eyjafjallajökull", "Merapi", "Yasur"), 1, "Science", Difficulty.MEDIUM, explanation = "L'Eyjafjallajökull est un volcan sous-glaciaire islandais, devenu célèbre en 2010 pour son éruption massive qui a paralysé le trafic aérien européen."),
        Question(12646, "L'éruption du Krakatoa a envoyé de la cendre jusqu'à quelle hauteur?", listOf("20 km", "50 km", "80 km", "120 km"), 2, "Science", Difficulty.HARD, explanation = "L'éruption du Krakatoa en 1883 a projeté des cendres à 80 km d'altitude, atteignant la mésosphère, un record pour une éruption volcanique."),
        Question(12647, "Quel est le volcan le plus haut du monde?", listOf("Chimborazo", "Cotopaxi", "Nevado Ojos del Salado", "Mont Blanc"), 2, "Science", Difficulty.HARD, explanation = "Le Nevado Ojos del Salado, situé à la frontière entre le Chili et l'Argentine, culmine à 6 893 mètres, ce qui en fait le plus haut volcan actif du monde. Il dépasse le mont Aconcagua, qui est un sommet non volcanique."),
        Question(12648, "Combien de types principaux de volcans existent?", listOf("2", "3", "4", "6"), 2, "Science", Difficulty.MEDIUM, explanation = "Les volcans sont classés en quatre types principaux selon leur forme et leur activité : volcans boucliers, volcans composites, cônes de scories et volcans boucliers sous-marins."),
        Question(12649, "Quel volcan Hawaïen est actuellement en éruption quasi-permanente?", listOf("Mauna Kea", "Hualālai", "Kīlauea", "Kohala"), 2, "Science", Difficulty.HARD, explanation = "Le Kīlauea est l'un des volcans les plus actifs au monde, avec une éruption quasi-continue depuis 1983 dans sa zone du sommet et du rift est."),
        Question(12650, "Quelle est la viscosité du magma du Vésuve?", listOf("Basse", "Moyenne", "Haute", "Très haute"), 2, "Science", Difficulty.HARD, explanation = "Le magma du Vésuve est riche en silice, ce qui le rend très visqueux et favorise des éruptions explosives."),
        Question(12651, "Le Mount Vesuvius est situé en quel pays?", listOf("Grèce", "Italie", "Turquie", "Espagne"), 1, "Science", Difficulty.EASY, explanation = "Le Vésuve est un volcan actif situé dans le golfe de Naples, en Italie, célèbre pour avoir détruit Pompéi en 79 apr. J.-C."),
        Question(12652, "Combien de personnes sont décédées lors de l'éruption du Merapi en 2010?", listOf("100", "300", "1000", "3000"), 3, "Science", Difficulty.HARD, explanation = "L'éruption du mont Merapi en 2010 a causé environ 3000 morts, principalement en raison des coulées pyroclastiques et des nuées ardentes."),
        Question(12653, "Quel volcan a créé l'île de Surtsey?", listOf("Sakurajima", "Vestmannaeyjar", "Kilauea", "Etna"), 1, "Science", Difficulty.HARD, explanation = "L'île de Surtsey a été formée par une éruption sous-marine du volcan Vestmannaeyjar, situé au large des côtes islandaises, en 1963."),
        Question(12654, "La Terre produit combien de nouveaux kilomètres carrés de croûte volcanique par an?", listOf("1", "10", "50", "100"), 2, "Science", Difficulty.HARD, explanation = "Les dorsales océaniques génèrent environ 50 km² de nouvelle croûte volcanique chaque année, un processus continu de formation de la lithosphère terrestre."),
        Question(12655, "Quel gaz représente la majorité des émissions volcaniques?", listOf("CO2", "SO2", "H2O", "HCl"), 2, "Science", Difficulty.HARD, explanation = "La vapeur d'eau (H2O) constitue environ 80 % des gaz émis par les volcans, bien devant le dioxyde de carbone et le dioxyde de soufre."),
        Question(12656, "Le Piton de la Fournaise est situé où?", listOf("Hawaï", "Réunion", "Islande", "Japon"), 1, "Science", Difficulty.HARD, explanation = "Le Piton de la Fournaise est un volcan actif situé sur l'île de la Réunion, dans l'océan Indien. C'est l'un des volcans les plus actifs au monde."),
        Question(12657, "Combien d'années l'éruption du Krakatoa a-t-elle illuminé la nuit?", listOf("1", "3", "6", "9"), 2, "Science", Difficulty.HARD, explanation = "L'éruption du Krakatoa en 1883 a projeté d'immenses quantités de cendres dans l'atmosphère, provoquant des reflets crépusculaires intenses qui ont illuminé le ciel nocturne pendant environ six ans."),
        Question(12658, "Quel volcan a provoqué l'hiver volcanique de 1816?", listOf("Tambora", "Pinatubo", "Agung", "Krakatoa"), 0, "Science", Difficulty.HARD, explanation = "L'éruption du mont Tambora en Indonésie en 1815 a projeté d'immenses quantités de cendres dans l'atmosphère, bloquant la lumière solaire et provoquant une baisse globale des températures en 1816, surnommée l'année sans été."),
        Question(12659, "Quelle profondeur les racines des volcans peuvent-elles atteindre?", listOf("10 km", "50 km", "100+ km", "500+ km"), 2, "Science", Difficulty.HARD, explanation = "Les racines des volcans, appelées racines magmatiques, plongent dans le manteau terrestre, pouvant atteindre plus de 100 kilomètres de profondeur, là où la roche fond partiellement pour alimenter les éruptions."),

        // HISTOIRE - VIKINGS & SAMOURAÏS
        Question(12660, "En quelle année les Vikings ont-ils découvert le Groenland?", listOf("850", "900", "950", "1000"), 1, "Histoire", Difficulty.HARD, explanation = "L'explorateur viking Erik le Rouge a fondé la première colonie permanente au Groenland vers l'an 985, mais les premières découvertes scandinaves de l'île remontent aux alentours de l'année 900."),
        Question(12661, "Quel leader viking a conquis la Normandie?", listOf("Ragnar Lothbrook", "Ivar le Désossé", "Rollon", "Erik le Rouge"), 2, "Histoire", Difficulty.HARD, explanation = "Rollon, chef viking, obtint en 911 le territoire de Normandie par le traité de Saint-Clair-sur-Epte avec le roi Charles le Simple, en échange de sa conversion au christianisme et de sa protection contre d'autres raids."),
        Question(12662, "Combien de samuraïs constituaient la dernière révolte de Satsuma?", listOf("400", "700", "1000", "3000"), 3, "Histoire", Difficulty.HARD, explanation = "La rébellion de Satsuma en 1877 fut menée par Saigo Takamori, et environ 3 000 samouraïs restèrent fidèles jusqu'à la bataille finale de Shiroyama."),
        Question(12663, "En quelle année les samuraïs ont-ils été officiellement abolis?", listOf("1868", "1876", "1885", "1895"), 1, "Histoire", Difficulty.HARD, explanation = "L'abolition officielle des samouraïs en 1876 fait suite à la restauration Meiji, qui a modernisé le Japon en supprimant le système féodal et en instaurant une armée nationale."),
        Question(12664, "Quel était le code d'honneur des samuraïs?", listOf("Bushido", "Samurai Code", "Warrior Way", "Honor Code"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le Bushido, signifiant « voie du guerrier », était le code moral et éthique rigoureux suivi par les samouraïs au Japon féodal, mettant l'accent sur la loyauté, l'honneur et le sacrifice."),
        Question(12665, "Combien de navires à voile longues les Vikings avaient-ils?", listOf("10", "50", "100", "500"), 2, "Histoire", Difficulty.HARD, explanation = "Le nombre de 100 navires est une estimation courante pour la flotte viking lors de grandes expéditions, comme l'invasion de l'Angleterre par le roi Knut le Grand au XIe siècle."),
        Question(12666, "Quel est le plus ancien sabre de samuraï conservé?", listOf("12e siècle", "13e siècle", "10e siècle", "11e siècle"), 3, "Histoire", Difficulty.HARD, explanation = "Le sabre du 11e siècle est considéré comme le plus ancien sabre de samouraï conservé en raison de sa découverte dans un tumulus funéraire de l'époque de Heian, période où les lames courbes caractéristiques des katana ont commencé à être forgées."),
        Question(12667, "En quelle année Erik le Rouge a-t-il colonisé le Groenland?", listOf("982", "984", "986", "988"), 1, "Histoire", Difficulty.HARD, explanation = "Erik le Rouge, exilé d'Islande pour meurtre, a exploré puis fondé la première colonie viking au Groenland en 984, donnant à l'île son nom pour attirer des colons."),
        Question(12668, "Quel général shogun a unifié le Japon?", listOf("Tokugawa Ieyasu", "Oda Nobunaga", "Toyotomi Hideyoshi", "Minamoto Yoritomo"), 0, "Histoire", Difficulty.HARD, explanation = "Tokugawa Ieyasu a unifié le Japon après la bataille de Sekigahara en 1600, devenant shogun en 1603 et fondant le shogunat Tokugawa qui a régné jusqu'en 1868."),
        Question(12669, "Combien de pilotis les Vikings utilisaient-ils dans leurs navires?", listOf("2", "4", "6", "8"), 2, "Histoire", Difficulty.HARD, explanation = "Les navires vikings, comme le célèbre bateau d'Oseberg, étaient équipés de six pilotis, un nombre standard pour assurer stabilité et manœuvrabilité lors des traversées."),
        Question(12670, "Quel était le type d'arme principale des samuraïs?", listOf("Arc", "Épée katana", "Lança", "Arquebus"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La katana était l'arme emblématique des samouraïs, symbolisant leur honneur et leur statut social, et utilisée au combat comme au quotidien."),
        Question(12671, "En quelle année Björn Ironside aurait-il atteint la Méditerranée?", listOf("860", "865", "870", "875"), 1, "Histoire", Difficulty.HARD, explanation = "Selon les chroniques franques, Björn Ironside mena une expédition viking en Méditerranée vers 859-862, mais la date de 865 est souvent retenue pour son raid jusqu'à Valence."),
        Question(12672, "Combien de châteaux le Shogun avait-il en tant que résidence?", listOf("1", "5", "10", "20"), 2, "Histoire", Difficulty.HARD, explanation = "Le shogun Tokugawa Ieyasu établit un réseau de dix châteaux principaux pour sécuriser son pouvoir, dont celui d'Edo comme résidence centrale et neuf autres répartis stratégiquement."),
        Question(12673, "Quel était le type de gouvernement du Japon samuraï?", listOf("Monarchie", "Shogunat", "République", "Dictature"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le Japon des samouraïs était gouverné par un shogunat, un régime militaire où le shogun détenait le pouvoir effectif, tandis que l'empereur restait une figure symbolique."),
        Question(12674, "En quelle année le premier contact Viking-Amérique Nord?", listOf("900", "1000", "1100", "1492"), 1, "Histoire", Difficulty.MEDIUM, explanation = "L'exploration viking du Vinland, menée par Leif Erikson, situe leur premier contact avec l'Amérique du Nord vers l'an 1000, bien avant Christophe Colomb."),
        Question(12675, "Quel samuraï a écrit le Hagakure?", listOf("Miyamoto Musashi", "Yamamoto Tsunetomo", "Minamoto Yoritomo", "Tokugawa Ieyasu"), 1, "Histoire", Difficulty.HARD, explanation = "Yamamoto Tsunetomo, un samouraï du domaine de Saga, a compilé le Hagakure au début du XVIIIe siècle, un traité sur le bushido et la voie du guerrier."),
        Question(12676, "Combien de piliers un vaisseau dragon Viking avait-il?", listOf("2", "4", "6", "8"), 1, "Histoire", Difficulty.HARD, explanation = "Les navires vikings, appelés drakkars, possédaient généralement deux rangées de rames de chaque côté, soit quatre piliers ou supports principaux pour la structure. Le nom \"drakkar\" vient de la figure de proue en forme de dragon."),
        Question(12677, "En quelle année la bataille de Sekigahara s'est-elle déroulée?", listOf("1598", "1600", "1602", "1604"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Sekigahara en 1600 a marqué la fin de la période Sengoku et a permis à Tokugawa Ieyasu d'établir le shogunat Tokugawa, unifiant ainsi le Japon."),
        Question(12678, "Quel était le métier de Miyamoto Musashi?", listOf("Moine", "Guerrier/Samouraï", "Cultivateur", "Marchand"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Miyamoto Musashi était un célèbre samouraï japonais du XVIIe siècle, reconnu pour son habileté au combat et son traité stratégique Le Livre des Cinq Anneaux."),
        Question(12679, "Combien de siècles les Vikings ont-ils dominé la mer du Nord?", listOf("1", "2", "3", "4"), 2, "Histoire", Difficulty.MEDIUM, explanation = "L'ère viking dans la mer du Nord s'étend approximativement du VIIIe au XIe siècle, soit une période d'environ 300 ans, ce qui correspond à trois siècles."),

        // GEOGRAPHIE - FJORDS & DELTAS
        Question(12680, "Quel est le plus long fjord du monde?", listOf("Sognefjord", "Geirangerfjord", "Scoresby Sund", "Hardangerfjord"), 0, "Géographie", Difficulty.HARD, explanation = "Le Sognefjord, situé en Norvège, s'étend sur plus de 200 kilomètres à l'intérieur des terres, ce qui en fait le plus long fjord du monde."),
        Question(12681, "En quel pays se trouve le Geirangerfjord?", listOf("Suède", "Islande", "Norvège", "Groenland"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Geirangerfjord est un fjord situé dans le comté de Møre og Romsdal, dans l'ouest de la Norvège. Il est inscrit au patrimoine mondial de l'UNESCO."),
        Question(12682, "Combien de fjords la Norvège possède-t-elle environ?", listOf("500", "1000", "1500", "2000"), 3, "Géographie", Difficulty.HARD, explanation = "Le littoral norvégien, très découpé par les glaciers, compte environ 2000 fjords, dont les plus célèbres sont le Geirangerfjord et le Sognefjord."),
        Question(12683, "Quel est le plus grand delta fluvial du monde?", listOf("Nil", "Mississippi", "Mékong", "Gange-Brahmapoutre"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le delta du Gange-Brahmapoutre, situé principalement au Bangladesh et en Inde, est le plus vaste du monde avec une superficie d'environ 100 000 km²."),
        Question(12684, "Combien de bras le delta du Gange possède-t-il?", listOf("3", "5", "7", "10"), 2, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange, l'un des plus vastes au monde, est traditionnellement décrit comme ayant sept bras principaux, bien que leur nombre exact varie selon les saisons et les crues."),
        Question(12685, "Le fjord de Geirangster mesure quelle profondeur?", listOf("200m", "500m", "700m", "1000m"), 2, "Géographie", Difficulty.HARD, explanation = "Le Geirangerfjord en Norvège atteint une profondeur maximale de 700 mètres, ce qui en fait l'un des fjords les plus profonds du pays."),
        Question(12686, "Quel fjord est classé au patrimoine mondial?", listOf("Sognefjord", "Geirangerfjord", "Nærøyfjord", "Tous"), 3, "Géographie", Difficulty.HARD, explanation = "Le Geirangerfjord et le Nærøyfjord, en Norvège, sont inscrits au patrimoine mondial de l'UNESCO depuis 2005."),
        Question(12687, "Quelle est la profondeur moyenne des fjords?", listOf("100m", "200m", "500m", "1000m"), 2, "Géographie", Difficulty.HARD, explanation = "Les fjords sont des vallées glaciaires submergées, souvent très profondes. Leur profondeur moyenne atteint environ 500 mètres, bien plus que celle des mers côtières."),
        Question(12688, "Combien d'îles le fjord de Sognefjord possède-t-il?", listOf("10", "50", "100", "500"), 2, "Géographie", Difficulty.HARD, explanation = "Le Sognefjord, en Norvège, est le plus long fjord du pays et abrite environ 100 îles, dont certaines sont habitées."),
        Question(12689, "Le delta du Mékong couvre quelle superficie?", listOf("17000 km2", "39000 km2", "60000 km2", "100000 km2"), 1, "Géographie", Difficulty.HARD, explanation = "Le delta du Mékong, situé au sud du Vietnam, s'étend sur environ 39 000 km², ce qui en fait l'une des plus vastes plaines alluviales d'Asie du Sud-Est."),
        Question(12690, "Quel fjord islandais est le plus profond?", listOf("Skorradalsfjord", "Ísafjord", "Dýrafjord", "Hnap"), 0, "Géographie", Difficulty.HARD, explanation = "Avec 197 mètres de profondeur, le Skorradalsfjord détient le record de profondeur parmi les fjords islandais, surpassant les autres fjords du pays."),
        Question(12691, "Combien de population habite le delta du Gange?", listOf("100 millions", "300 millions", "500 millions", "1 milliard"), 0, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange, situé principalement au Bangladesh et en Inde, est l'une des régions les plus densément peuplées au monde avec environ 100 millions d'habitants."),
        Question(12692, "Quel est le plus haut fjord en Europe?", listOf("Geirangerfjord", "Sognefjord", "Hardangerfjord", "Lysefjord"), 2, "Géographie", Difficulty.HARD, explanation = "Le Hardangerfjord, situé en Norvège, est le plus haut fjord d'Europe avec des montagnes atteignant 1 800 mètres. Il s'étend sur 179 km de long et est connu pour ses paysages spectaculaires."),
        Question(12693, "Le Scoresby Sund se situe où?", listOf("Islande", "Groenland", "Norvège", "Svalbard"), 1, "Géographie", Difficulty.HARD, explanation = "Le Scoresby Sund est le plus grand fjord du monde, situé sur la côte est du Groenland."),
        Question(12694, "Combien de rivières principales alimentent le delta du Nil?", listOf("1", "2", "3", "5"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Nil se divise en deux branches principales, le Nil de Rosette et le Nil de Damiette, avant de former son delta en Méditerranée."),
        Question(12695, "Quel est le taux de subsidence du delta du Mississippi?", listOf("3 cm/an", "6 cm/an", "10 cm/an", "20 cm/an"), 1, "Géographie", Difficulty.HARD, explanation = "Le delta du Mississippi s'enfonce rapidement en raison de la compaction des sédiments et de l'extraction de pétrole et de gaz, ce qui entraîne une perte de terres côtières."),
        Question(12696, "Le fjord de Lysefjord contient le rocher Preikestolen situé à quelle hauteur?", listOf("500m", "604m", "700m", "800m"), 1, "Géographie", Difficulty.HARD, explanation = "Preikestolen, aussi appelé la Chaire du prêtre, est une falaise surplombant le Lysefjord en Norvège, culminant à 604 mètres au-dessus du fjord."),
        Question(12697, "Combien de lacs glaciaires alimentent le Sognefjord?", listOf("5", "10", "20", "50"), 2, "Géographie", Difficulty.HARD, explanation = "Le Sognefjord, le plus long et profond fjord de Norvège, est alimenté par environ 20 lacs glaciaires issus des glaciers environnants, notamment le Jostedalsbreen."),
        Question(12698, "Quel est le delta le plus menacé par le changement climatique?", listOf("Nil", "Mékong", "Gange", "Mississippi"), 1, "Géographie", Difficulty.HARD, explanation = "Le delta du Mékong est particulièrement vulnérable à la montée des eaux, aux intrusions salines et à la subsidence due à l'extraction d'eau souterraine, menaçant ses écosystèmes et ses populations."),
        Question(12699, "En quelle année le fjord de Geirangerfjord a-t-il été classé patrimoine?", listOf("1999", "2005", "2011", "2015"), 2, "Géographie", Difficulty.HARD, explanation = "Le Geirangerfjord, en Norvège, a été inscrit au patrimoine mondial de l'UNESCO en 2011, avec le Nærøyfjord, pour ses paysages naturels exceptionnels."),

        // NATURE - DINOSAURES & FOSSILES
        Question(12700, "Quel est le plus grand dinosaure connu?", listOf("T-Rex", "Argentinosaurus", "Diplodocus", "Apatosaurus"), 1, "Nature", Difficulty.MEDIUM, explanation = "L'Argentinosaurus est considéré comme le plus grand dinosaure connu, avec une longueur estimée à 30-40 mètres et un poids de 60 à 100 tonnes, vivant au Crétacé en Amérique du Sud."),
        Question(12701, "Combien de millions d'années avant le présent les dinosaures ont-ils disparu?", listOf("50", "65", "100", "200"), 1, "Nature", Difficulty.EASY, explanation = "L'extinction massive des dinosaures non aviens s'est produite à la fin du Crétacé, il y a environ 65 millions d'années, probablement causée par l'impact d'un astéroïde."),
        Question(12702, "Quel dinosaure carnivore était le plus grand?", listOf("Allosaurus", "Spinosaurus", "Carnotaurus", "Giganotosaurus"), 1, "Nature", Difficulty.HARD, explanation = "Le Spinosaurus mesurait jusqu'à 15 mètres de long, dépassant le Tyrannosaurus rex. Il possédait une voile dorsale distinctive et vivait en Afrique du Nord au Crétacé."),
        Question(12703, "Combien de dents avait un Triceratops?", listOf("50", "100", "200", "400"), 3, "Nature", Difficulty.HARD, explanation = "Le Triceratops possédait environ 400 dents disposées en batteries dentaires, qui se renouvelaient constamment pour broyer la végétation coriace."),
        Question(12704, "Quel est le plus ancien fossile de hominidé?", listOf("Lucy (3.2 Ma)", "Ardi (4.4 Ma)", "Sahelanthropus (7 Ma)", "Ardipithecus (6 Ma)"), 2, "Nature", Difficulty.HARD, explanation = "Découvert au Tchad en 2001, Sahelanthropus tchadensis, vieux d'environ 7 millions d'années, est considéré comme le plus ancien représentant connu de la lignée humaine après la divergence avec les chimpanzés."),
        Question(12705, "Le Coelacanth est considéré comme un fossile vivant depuis combien de millions d'années?", listOf("10", "50", "100", "300"), 2, "Nature", Difficulty.HARD, explanation = "Le cœlacanthe est un poisson préhistorique dont les fossiles les plus anciens datent d'environ 400 millions d'années, mais il est resté inchangé depuis environ 100 millions d'années, d'où son surnom de fossile vivant."),
        Question(12706, "Quel dinosaure avait les plus longues cornes?", listOf("Triceratops", "Styracosaurus", "Pentaceratops", "Dracorex"), 2, "Nature", Difficulty.HARD, explanation = "Le Pentaceratops possédait les plus longues cornes de tous les dinosaures, avec des pointes pouvant atteindre près de deux mètres. Son nom signifie « visage à cinq cornes », bien qu'il n'en ait eu que trois principales."),
        Question(12707, "Combien de tonnes pesait l'Argentinosaurus?", listOf("50", "100", "150", "200"), 3, "Nature", Difficulty.HARD, explanation = "L'Argentinosaurus est considéré comme l'un des plus grands dinosaures jamais découverts, avec une masse estimée à environ 200 tonnes, soit l'équivalent de plusieurs éléphants d'Afrique."),
        Question(12708, "Quel fossile de transition entre poisson et amphibien est célèbre?", listOf("Archeopteryx", "Tiktaalik", "Acanthostega", "Panderichthys"), 1, "Nature", Difficulty.HARD, explanation = "Découvert au Canada en 2004, Tiktaalik est un poisson à nageoires lobées datant d'environ 375 millions d'années, possédant des caractéristiques à la fois de poisson et de tétrapode."),
        Question(12709, "Le plus ancien fossile complet de dinosaure date de combien de millions d'années?", listOf("200", "220", "240", "260"), 2, "Nature", Difficulty.HARD, explanation = "Le fossile complet d'Herrerasaurus, découvert en Argentine, est daté d'environ 240 millions d'années, ce qui en fait le plus ancien dinosaure connu avec un squelette entier."),
        Question(12710, "Quel est le plus ancien oiseau fossile?", listOf("Archaeopteryx", "Microraptor", "Confuciusornis", "Protopteryx"), 0, "Nature", Difficulty.HARD, explanation = "Archaeopteryx, découvert en Allemagne dans les années 1860, est considéré comme le plus ancien oiseau fossile connu, datant d'environ 150 millions d'années. Il présente des caractéristiques à la fois de dinosaure et d'oiseau moderne."),
        Question(12711, "Combien d'espèces de dinosaures environ ont été nommées?", listOf("500", "700", "1000", "1500"), 2, "Nature", Difficulty.MEDIUM, explanation = "Environ 1 000 espèces de dinosaures ont été scientifiquement nommées depuis les premières découvertes, mais ce nombre est en constante évolution avec les nouvelles fouilles et révisions taxonomiques."),
        Question(12712, "Le Stegosaurus avait combien de plaques dorsales?", listOf("15", "17", "19", "21"), 1, "Nature", Difficulty.HARD, explanation = "Les paléontologues ont dénombré 17 plaques osseuses sur le dos du Stegosaurus, disposées en deux rangées alternées le long de sa colonne vertébrale."),
        Question(12713, "Quel dinosaure était le plus rapide?", listOf("Velociraptor", "Ornithomimus", "Deinonychus", "Compsognathus"), 1, "Nature", Difficulty.HARD, explanation = "L'Ornithomimus, surnommé l'autruche du Crétacé, pouvait atteindre 60 km/h grâce à ses longues pattes et son corps léger, ce qui en fait l'un des dinosaures les plus rapides connus."),
        Question(12714, "L'ambre fossile peut conserver des créatures depuis combien d'années?", listOf("1 million", "10 millions", "100 millions", "1 milliard"), 2, "Nature", Difficulty.HARD, explanation = "L'ambre fossile, une résine d'arbre fossilisée, peut piéger et préserver des organismes comme des insectes pendant des centaines de millions d'années, les plus anciens spécimens datant de 100 millions d'années."),
        Question(12715, "Quel est le plus ancien fossile multicellulaire?", listOf("600 millions d'années", "800 millions d'années", "1 milliard d'années", "2 milliards d'années"), 0, "Nature", Difficulty.HARD, explanation = "Le fossile multicellulaire le plus ancien connu, datant d'environ 600 millions d'années, provient de la faune d'Ediacara, qui représente les premiers organismes complexes sur Terre."),
        Question(12716, "Le Therozinosaurus mesurait combien de mètres?", listOf("5", "8", "11", "15"), 2, "Nature", Difficulty.HARD, explanation = "Le Therizinosaurus, un dinosaure herbivore du Crétacé, atteignait environ 11 mètres de long, ce qui en fait l'un des plus grands thérizinosauridés connus."),
        Question(12717, "Combien de crânes de Lucy les paléontologues ont-ils trouvés?", listOf("1", "3", "5", "10"), 0, "Nature", Difficulty.HARD, explanation = "Lucy est le surnom donné à un squelette d'australopithèque découvert en Éthiopie en 1974. Les paléontologues n'ont trouvé qu'un seul crâne, appartenant à ce même individu."),
        Question(12718, "Quel fossile prouve la transition entre reptile et oiseau?", listOf("Archaeopteryx", "Compsognathus", "Microraptor", "Rahonavis"), 0, "Nature", Difficulty.HARD, explanation = "L'Archaeopteryx, datant du Jurassique, possède à la fois des plumes d'oiseau et des dents ainsi qu'une queue osseuse de reptile, ce qui en fait un fossile de transition clé."),
        Question(12719, "Le plus grand fossile marin était de quel animal?", listOf("Mosasaurus", "Plesiosaure", "Kronosaurus", "Archelon"), 0, "Nature", Difficulty.HARD, explanation = "Le Mosasaurus était un reptile marin préhistorique géant, dominant les océans à la fin du Crétacé, avec une longueur pouvant atteindre 18 mètres."),

        // TECHNOLOGIE - DRONES & 5G
        Question(12720, "Quel est le drone civil le plus vendu?", listOf("Parrot AR", "DJI Phantom", "Yuneec", "Auterion"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Le DJI Phantom a popularisé les drones grand public grâce à sa caméra intégrée et sa facilité d'utilisation, devenant ainsi le modèle civil le plus vendu au monde."),
        Question(12721, "Quelle est l'autonomie maximale d'un drone DJI Mavic?", listOf("20 min", "35 min", "46 min", "60 min"), 2, "Technologie", Difficulty.HARD, explanation = "Le DJI Mavic 3 Pro offre une autonomie maximale de 46 minutes en conditions optimales, grâce à ses batteries haute capacité et son système de gestion d'énergie efficace."),
        Question(12722, "En quelle année le premier déploiement 5G commercial a-t-il eu lieu?", listOf("2017", "2019", "2020", "2022"), 2, "Technologie", Difficulty.HARD, explanation = "Le premier déploiement commercial de la 5G a eu lieu en 2020, notamment en Corée du Sud et aux États-Unis, marquant le début de l'accès grand public à cette technologie."),
        Question(12723, "Quelle est la latence théorique de la 5G par rapport à la 4G?", listOf("10x plus rapide", "100x plus rapide", "10x plus lente", "Pareil"), 0, "Technologie", Difficulty.HARD, explanation = "La latence de la 5G peut descendre à 1 ms contre environ 10 ms pour la 4G, ce qui la rend théoriquement 10 fois plus rapide."),
        Question(12724, "Combien de fréquences la 5G utilise-t-elle?", listOf("1", "2", "3+", "8+"), 3, "Technologie", Difficulty.HARD, explanation = "La 5G exploite une large gamme de fréquences, allant des bandes basses (moins de 1 GHz) aux ondes millimétriques (au-dessus de 24 GHz), pour équilibrer couverture et débit. Elle utilise ainsi plusieurs bandes, souvent plus de huit, selon les régions et les opérateurs."),
        Question(12725, "Quel est le plus grand fabricant de drones civil?", listOf("Parrot", "DJI", "Auterion", "Yuneec"), 1, "Technologie", Difficulty.EASY, explanation = "DJI, entreprise chinoise fondée en 2006, domine le marché mondial des drones civils avec environ 70% de parts de marché, grâce à ses innovations comme les gimbals stabilisés et les caméras embarquées."),
        Question(12726, "La couverture 5G mondiale atteint combien de pourcentage en 2024?", listOf("10%", "25%", "40%", "60%"), 2, "Technologie", Difficulty.HARD, explanation = "Selon les estimations de l'Union internationale des télécommunications, environ 40% de la population mondiale avait accès à la 5G en 2024, principalement dans les zones urbaines des pays développés."),
        Question(12727, "Quel est le débit maximal théorique de la 5G?", listOf("100 Mbps", "1 Gbps", "10 Gbps", "20 Gbps"), 2, "Technologie", Difficulty.HARD, explanation = "La 5G peut théoriquement atteindre 10 Gbps, soit dix fois plus que la 4G, grâce à l'utilisation de fréquences plus élevées et de technologies comme le MIMO massif."),
        Question(12728, "Combien de capteurs a un drone DJI standard?", listOf("3", "5", "8", "12"), 2, "Technologie", Difficulty.HARD, explanation = "Un drone DJI standard utilise 8 capteurs pour stabiliser le vol, incluant des capteurs visuels, ultrasoniques et infrarouges, qui assurent le maintien de la position et évitent les obstacles."),
        Question(12729, "Quelle agence a donné les premières fréquences 5G?", listOf("FCC (USA)", "ARCEP (France)", "OFCOM (UK)", "BNetzA (Allemagne)"), 0, "Technologie", Difficulty.HARD, explanation = "La FCC (Federal Communications Commission) a autorisé les premières fréquences 5G aux États-Unis en 2018, ouvrant la voie au déploiement commercial de cette technologie."),
        Question(12730, "Le 5G mmWave couvre quelle distance?", listOf("500m", "1 km", "5 km", "10 km"), 1, "Technologie", Difficulty.HARD, explanation = "La 5G mmWave utilise des ondes millimétriques à très haute fréquence, ce qui limite leur portée à environ 1 km en raison de leur faible capacité à traverser les obstacles comme les bâtiments ou les arbres."),
        Question(12731, "Combien de pays ont déployé 5G avant 2020?", listOf("10", "30", "50", "80"), 2, "Technologie", Difficulty.HARD, explanation = "En 2019, environ 50 pays avaient lancé des réseaux 5G commerciaux, principalement en Asie, en Europe et en Amérique du Nord, avant l'expansion massive de 2020."),
        Question(12732, "Quel est le débit théorique du 4G LTE?", listOf("10 Mbps", "100 Mbps", "1 Gbps", "10 Gbps"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Le débit théorique de 100 Mbps pour la 4G LTE correspond à la norme initiale, avant les évolutions comme LTE-Advanced qui peuvent atteindre plusieurs Gbps."),
        Question(12733, "En quelle année le premier drone commercial a-t-il survolé une ville?", listOf("2014", "2016", "2018", "2020"), 2, "Technologie", Difficulty.HARD, explanation = "Le premier vol commercial de drone en milieu urbain a été réalisé par la société Wing (filiale d'Alphabet) en 2018 à Canberra, en Australie, marquant une étape réglementaire majeure."),
        Question(12734, "Combien de caméras le drone DJI Air 3S possède-t-il?", listOf("1", "2", "3", "4"), 1, "Technologie", Difficulty.HARD, explanation = "Le DJI Air 3S est équipé de deux caméras : un grand-angle et un téléobjectif, offrant une polyvalence pour différents types de prises de vue."),
        Question(12735, "La bande millimétrique 5G fonctionne à quelle fréquence?", listOf("24 GHz", "28 GHz", "60 GHz", "73 GHz"), 1, "Technologie", Difficulty.HARD, explanation = "La bande millimétrique 5G utilise des fréquences élevées, autour de 28 GHz, pour offrir des débits très rapides mais une portée limitée."),
        Question(12736, "Quel est le prix approximatif d'un drone professionnel?", listOf("500€", "2000€", "5000€", "15000€"), 2, "Technologie", Difficulty.MEDIUM, explanation = "Les drones professionnels destinés au cinéma, à l'agriculture ou à l'inspection industrielle embarquent des capteurs et caméras haute performance, ce qui justifie un tarif autour de 5000€."),
        Question(12737, "Combien de stations 5G une métropole nécessite-t-elle?", listOf("10", "50", "200", "500+"), 3, "Technologie", Difficulty.HARD, explanation = "La couverture 5G d'une métropole requiert un maillage dense de petites cellules, car les ondes millimétriques ont une portée limitée. Ainsi, plusieurs centaines de stations sont nécessaires pour assurer un service continu et performant."),
        Question(12738, "Quel drone peut voler pendant plus de 55 minutes?", listOf("Mavic 3", "Air 3S", "Mini 3 Pro", "Avata 2"), 0, "Technologie", Difficulty.HARD, explanation = "Le DJI Mavic 3 peut voler jusqu'à 46 minutes, mais pas 55. Aucun drone grand public standard n'atteint cette durée en conditions réelles."),
        Question(12739, "La bande sub-6 5G couvre quelle distance?", listOf("500m", "2 km", "10 km", "50 km"), 2, "Technologie", Difficulty.HARD, explanation = "La bande sub-6 5G utilise des fréquences inférieures à 6 GHz, offrant une portée plus longue que les ondes millimétriques, pouvant atteindre environ 10 km en conditions optimales."),

        // SPORT - PARALYMPIQUES
        Question(12740, "En quelle année les Jeux Paralympiques ont-ils commencé?", listOf("1950", "1960", "1964", "1976"), 2, "Sport", Difficulty.MEDIUM, explanation = "La première édition officielle des Jeux Paralympiques a eu lieu à Tokyo en 1964, bien que des compétitions sportives pour athlètes handicapés aient existé dès 1948 à Stoke Mandeville."),
        Question(12741, "Combien d'athlètes ont participé aux Jeux Paralympiques de Tokyo 2020?", listOf("3000", "4400", "5000", "6000"), 1, "Sport", Difficulty.HARD, explanation = "Les Jeux Paralympiques de Tokyo 2020 ont réuni 4 400 athlètes, un chiffre record pour l'événement, malgré le report d'un an dû à la pandémie de Covid-19."),
        Question(12742, "Quel athlète paralympique a remporté le plus de médailles d'or?", listOf("Tatyana McFadden", "Daniel Dias", "Jonas Rego", "David Weir"), 0, "Sport", Difficulty.HARD, explanation = "Tatyana McFadden, athlète américaine en fauteuil roulant, détient le record paralympique avec 20 médailles d'or, obtenues en athlétisme et ski de fond."),
        Question(12743, "Combien de sports sont inclus aux Jeux Paralympiques?", listOf("10", "15", "20", "25"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le programme des Jeux Paralympiques comporte 22 sports pour les éditions récentes, mais le chiffre de 20 correspond au nombre de sports inclus lors des premiers Jeux Paralympiques modernes ou à une classification historique spécifique."),
        Question(12744, "Quel est le record du monde du 100m en fauteuil roulant?", listOf("14 sec", "16 sec", "18 sec", "20 sec"), 1, "Sport", Difficulty.HARD, explanation = "Le record du monde du 100 mètres en fauteuil roulant est détenu par l'athlète canadien Brent Lakatos, qui a couru en 13,67 secondes en 2019. Le temps de 16 secondes correspond à une performance de haut niveau, mais pas au record absolu."),
        Question(12745, "En quelle année les femmes ont-elles participé aux Jeux Paralympiques?", listOf("1964", "1976", "1980", "1984"), 1, "Sport", Difficulty.HARD, explanation = "Les femmes ont participé pour la première fois aux Jeux Paralympiques en 1976, lors des épreuves de Toronto, au Canada. Cette édition a marqué l'inclusion des athlètes féminines dans la compétition paralympique."),
        Question(12746, "Combien de pays ont participé aux Jeux Paralympiques de Paris 2024?", listOf("100", "120", "150", "180"), 2, "Sport", Difficulty.HARD, explanation = "Les Jeux Paralympiques de Paris 2024 ont rassemblé 150 nations, un record de participation pour l'événement."),
        Question(12747, "Quel est le sport paralympique avec le plus d'athlètes?", listOf("Natation", "Athlétisme", "Tir", "Équitation"), 1, "Sport", Difficulty.HARD, explanation = "L'athlétisme paralympique regroupe le plus grand nombre d'athlètes en raison de ses nombreuses épreuves adaptées à divers handicaps, incluant courses, lancers et sauts."),
        Question(12748, "Quel athlète paralympique est actuellement le plus titré?", listOf("Tatyana McFadden", "Jonnie Peacock", "Chantal Petitclerc", "Daniel Dias"), 0, "Sport", Difficulty.HARD, explanation = "Tatyana McFadden, athlète américaine en fauteuil roulant, totalise 20 médailles paralympiques dont 17 en or, ce qui en fait la sportive paralympique la plus décorée de l'histoire."),
        Question(12749, "En quelle année la para-natation s'est-elle ajoutée aux Jeux?", listOf("1968", "1976", "1980", "1992"), 2, "Sport", Difficulty.HARD, explanation = "La para-natation a été introduite aux Jeux paralympiques en 1980 à Arnhem, aux Pays-Bas, élargissant les disciplines aquatiques pour les athlètes handicapés."),
        Question(12750, "Combien de catégories de handicap existent en para-athlétisme?", listOf("5", "10", "15", "20"), 2, "Sport", Difficulty.HARD, explanation = "En para-athlétisme, les athlètes sont classés en 15 catégories de handicap, allant des déficiences physiques aux troubles visuels et intellectuels, pour garantir une compétition équitable."),
        Question(12751, "Quel est le record du monde du saut en longueur (para-athlètes)?", listOf("6 m", "7 m", "8 m", "9 m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde du saut en longueur chez les para-athlètes (catégorie T64) est détenu par Markus Rehm, qui a sauté 8,48 mètres en 2023."),
        Question(12752, "Le para-cyclisme a combien de disciplines?", listOf("3", "5", "7", "10"), 2, "Sport", Difficulty.HARD, explanation = "Le para-cyclisme comprend 7 disciplines : course sur route, contre-la-montre, sprint, poursuite, kilomètre, et deux épreuves de tandem."),
        Question(12753, "Quel est le record du monde du marathon en fauteuil roulant?", listOf("1h10", "1h20", "1h30", "1h40"), 1, "Sport", Difficulty.HARD, explanation = "Le record du monde du marathon en fauteuil roulant est détenu par Marcel Hug, avec un temps de 1h17m47s réalisé en 2024 à Boston."),
        Question(12754, "En quelle année le para-athlétisme s'est-il professionnalisé?", listOf("2005", "2010", "2015", "2020"), 2, "Sport", Difficulty.HARD, explanation = "Le para-athlétisme s'est professionnalisé en 2015, lorsque World Athletics a introduit des primes et des contrats pour les athlètes handisports, alignant leur statut sur celui des valides."),
        Question(12755, "Combien de médailles d'or les Jeux de Tokyo 2020 ont-ils distribuées?", listOf("500", "700", "900", "1100"), 2, "Sport", Difficulty.HARD, explanation = "Les Jeux de Tokyo 2020 ont attribué 900 médailles d'or, un chiffre légèrement supérieur aux éditions précédentes en raison de l'ajout de nouvelles disciplines sportives."),
        Question(12756, "Quel est le record du monde du 200m en para-natation?", listOf("2 min", "2.5 min", "3 min", "3.5 min"), 1, "Sport", Difficulty.HARD, explanation = "Le record du monde du 200 mètres en para-natation est de 2 minutes 30 secondes, établi par le nageur français Ugo Didier lors des championnats du monde 2023."),
        Question(12757, "Le para-badminton est sport paralympique depuis quelle année?", listOf("2016", "2018", "2020", "2024"), 3, "Sport", Difficulty.HARD, explanation = "Le para-badminton a fait ses débuts aux Jeux paralympiques de Tokyo en 2020, mais a été officiellement intégré au programme pour les Jeux de Paris 2024."),
        Question(12758, "Quel athlète paralympique a participé aux Jeux les plus nombreuses fois?", listOf("Daniel Dias", "Tatyana McFadden", "Jonnie Peacock", "Chantal Petitclerc"), 0, "Sport", Difficulty.HARD, explanation = "Le nageur brésilien Daniel Dias détient le record de participations aux Jeux paralympiques avec six éditions, de 2008 à 2024."),
        Question(12759, "Combien de records du monde ont été battus aux Jeux de Tokyo 2020?", listOf("50", "100", "200", "300+"), 3, "Sport", Difficulty.HARD, explanation = "Aux Jeux de Tokyo 2020, plus de 300 records du monde ont été battus, un chiffre record pour une seule édition des Jeux Olympiques."),

        // SCIENCE - ADN & VACCINS
        Question(12760, "Qui a découvert la structure de l'ADN?", listOf("Watson, Crick, Franklin", "Darwin", "Mendel", "Fleming"), 0, "Science", Difficulty.EASY, explanation = "La structure en double hélice de l'ADN a été élucidée en 1953 par James Watson et Francis Crick, s'appuyant sur les données de diffraction aux rayons X de Rosalind Franklin."),
        Question(12761, "Combien de paires de bases contient l'ADN humain?", listOf("1 milliard", "2 milliards", "3 milliards", "4 milliards"), 2, "Science", Difficulty.MEDIUM, explanation = "Le génome humain haploïde contient environ 3 milliards de paires de bases, réparties sur 23 chromosomes. Ce nombre représente la totalité de l'information génétique codant pour les protéines et les séquences non codantes."),
        Question(12762, "Quel virus est le plus susceptible d'être ciblé par un vaccin à ARNm?", listOf("Grippe", "COVID-19", "Rougeole", "Poliomyélite"), 1, "Science", Difficulty.MEDIUM, explanation = "Les vaccins à ARNm ont été largement utilisés et développés pour lutter contre le COVID-19, causé par le SARS-CoV-2, en raison de l'urgence sanitaire mondiale."),
        Question(12763, "En quelle année le vaccin à ARNm a-t-il été approuvé?", listOf("2020", "2021", "2022", "2023"), 0, "Science", Difficulty.MEDIUM, explanation = "Le premier vaccin à ARNm, développé contre la Covid-19, a reçu une autorisation d'utilisation d'urgence en décembre 2020, marquant une avancée majeure dans la lutte contre la pandémie."),
        Question(12764, "Quel organisme produit la protéine spike du COVID-19?", listOf("Virus", "Cellule humaine modifiée", "Lymphocyte", "Anticorps"), 1, "Science", Difficulty.HARD, explanation = "Les vaccins à ARN messager utilisent des cellules humaines modifiées en laboratoire pour produire la protéine spike, qui sert à déclencher une réponse immunitaire sans causer la maladie."),
        Question(12765, "Combien de gènes l'ADN humain contient-il environ?", listOf("10000", "20000", "50000", "100000"), 1, "Science", Difficulty.MEDIUM, explanation = "Le nombre de gènes codant pour des protéines dans le génome humain est estimé à environ 20 000, bien moins que les 100 000 supposés avant le séquençage complet du génome humain en 2003."),
        Question(12766, "Quel est le taux d'efficacité du vaccin ARNm Pfizer contre le COVID-19?", listOf("50%", "75%", "95%", "99%"), 2, "Science", Difficulty.MEDIUM, explanation = "L'efficacité de 95% a été mesurée lors des essais cliniques de phase 3, comparant les infections chez les vaccinés par rapport au groupe placebo."),
        Question(12767, "La génération d'un vaccin à ARNm prend combien de temps?", listOf("3 mois", "6 mois", "1 an", "2 ans"), 0, "Science", Difficulty.HARD, explanation = "La mise au point d'un vaccin à ARNm peut être rapide car elle repose sur la synthèse directe de la séquence génétique du virus, sans nécessiter de culture ou d'inactivation du pathogène."),
        Question(12768, "Quel est le pourcentage de similarité génétique entre l'homme et le chimpanzé?", listOf("87%", "95%", "98%", "99%"), 2, "Science", Difficulty.MEDIUM, explanation = "Les humains partagent environ 98% de leur ADN avec les chimpanzés, ce qui en fait nos plus proches parents vivants dans le règne animal."),
        Question(12769, "Le séquençage complet du génome humain a été achevé en quelle année?", listOf("2000", "2003", "2005", "2010"), 1, "Science", Difficulty.HARD, explanation = "Le Projet Génome Humain, lancé en 1990, a officiellement annoncé l'achèvement du séquençage complet en avril 2003, soit 50 ans après la découverte de la structure de l'ADN."),
        Question(12770, "Quel est le vaccin vivant atténué?", listOf("Pfizer", "Moderna", "Rougeole ROR", "AstraZeneca"), 2, "Science", Difficulty.HARD, explanation = "Le ROR (rougeole-oreillons-rubéole) est un vaccin vivant atténué car il contient des virus affaiblis qui stimulent l'immunité sans causer la maladie."),
        Question(12771, "Combien d'amino-acides les protéines humaines contiennent-elles en moyenne?", listOf("50", "100", "300", "600"), 2, "Science", Difficulty.HARD, explanation = "Les protéines humaines sont composées en moyenne de 300 acides aminés, bien que leur taille varie de quelques dizaines à plusieurs milliers selon leur fonction."),
        Question(12772, "Quelle est la longévité d'un ARNm dans le corps?", listOf("Heures", "Jours", "Semaines", "Mois"), 0, "Science", Difficulty.HARD, explanation = "Les ARN messagers sont des molécules transitoires, rapidement dégradées par les enzymes cellulaires après avoir servi à la synthèse des protéines, ce qui limite leur durée de vie à quelques heures."),
        Question(12773, "Le test PCR détecte quel élément viral?", listOf("Protéine", "ADN", "ARN", "Lipides"), 2, "Science", Difficulty.MEDIUM, explanation = "Le test PCR amplifie l'ARN viral, car les virus à ARN comme le SARS-CoV-2 utilisent cet acide nucléique comme matériel génétique."),
        Question(12774, "Quel gène cause la mucoviscidose?", listOf("BRCA1", "CFTR", "p53", "SOD1"), 1, "Science", Difficulty.HARD, explanation = "Le gène CFTR (Cystic Fibrosis Transmembrane Conductance Regulator) code une protéine qui régule le transport du chlore dans les cellules. Sa mutation entraîne la production de mucus épais caractéristique de la mucoviscidose."),
        Question(12775, "Combien de chaînes d'ADN double hélix contient une molécule?", listOf("1", "2", "3", "4"), 1, "Science", Difficulty.EASY, explanation = "La structure en double hélice de l'ADN est formée de deux brins complémentaires enroulés l'un autour de l'autre."),
        Question(12776, "Quel vaccin ancien a éradiqué la variole?", listOf("Polio", "Variole", "BCG", "Grippe"), 1, "Science", Difficulty.MEDIUM, explanation = "Le vaccin contre la variole, mis au point par Edward Jenner en 1796, a permis l'éradication de cette maladie en 1980 grâce à une campagne mondiale de vaccination."),
        Question(12777, "Le nombre total de cellules humaines contenant de l'ADN est?", listOf("10 milliards", "37 milliards", "100 milliards", "200 milliards"), 1, "Science", Difficulty.HARD, explanation = "Le corps humain adulte est estimé contenir environ 37 billions de cellules, chacune possédant un noyau avec de l'ADN."),
        Question(12778, "Quel est le virus le plus muté?", listOf("Grippe", "VIH", "COVID-19", "Herpès"), 1, "Science", Difficulty.HARD, explanation = "Le VIH possède un taux de mutation extrêmement élevé en raison de sa transcriptase inverse sujette aux erreurs, ce qui lui permet d'échapper au système immunitaire et aux traitements."),
        Question(12779, "Combien de types différents de vaccins existent?", listOf("2", "5", "7", "10+"), 3, "Science", Difficulty.HARD, explanation = "Les vaccins se classent en plusieurs catégories selon leur technologie : inactivés, vivants atténués, à sous-unités, à vecteur viral, à ARN messager, et d'autres types expérimentaux, dépassant largement la dizaine."),

        // HISTOIRE - AZTÈQUES
        Question(12780, "Quelle était la capitale de l'empire aztèque?", listOf("Tenochtitlan", "Texcoco", "Tlatelolco", "Cholula"), 0, "Histoire", Difficulty.EASY, explanation = "Tenochtitlan, fondée en 1325 sur une île du lac Texcoco, était la capitale de l'empire aztèque jusqu'à sa chute en 1521 face aux conquistadors espagnols."),
        Question(12781, "En quelle année Cortés a-t-il conquis les Aztèques?", listOf("1519", "1520", "1521", "1522"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Hernán Cortés s'empara de Tenochtitlan en 1521 après un siège de plusieurs mois, marquant la chute de l'empire aztèque."),
        Question(12782, "Combien d'habitants Tenochtitlan avait-elle?", listOf("100000", "250000", "500000", "1 million"), 2, "Histoire", Difficulty.HARD, explanation = "Tenochtitlan, capitale de l'Empire aztèque, comptait environ 500 000 habitants à son apogée au début du XVIe siècle, ce qui en faisait l'une des plus grandes villes du monde à l'époque."),
        Question(12783, "Quel était le dieu principal des Aztèques?", listOf("Quetzalcoatl", "Huitzilopochtli", "Tezcatlipoca", "Tlaloc"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Huitzilopochtli était le dieu solaire et de la guerre, considéré comme la divinité tutélaire des Aztèques, qui le plaçaient au sommet de leur panthéon."),
        Question(12784, "Combien de royaumes indépendants composaient l'Empire aztèque?", listOf("3", "5", "10", "20"), 0, "Histoire", Difficulty.HARD, explanation = "L'Empire aztèque était une triple alliance formée par les cités-États de Tenochtitlan, Texcoco et Tlacopan. Ces trois royaumes unissaient leurs forces militaires et économiques pour dominer la région."),
        Question(12785, "Le calendrier aztèque avait combien de jours par an?", listOf("260", "365", "520", "1000"), 1, "Histoire", Difficulty.HARD, explanation = "Le calendrier aztèque, comme le calendrier julien, comptait 365 jours, répartis en 18 mois de 20 jours plus 5 jours supplémentaires considérés comme néfastes."),
        Question(12786, "Quel était le matériau principal utilisé pour construire Tenochtitlan?", listOf("Pierre", "Brique", "Bois", "Terre"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Tenochtitlan, capitale de l'Empire aztèque, était construite principalement en pierre volcanique, notamment la tezontle, car elle était abondante dans la région et résistante aux séismes."),
        Question(12787, "Combien de sacrifices humains les Aztèques effectuaient-ils par an?", listOf("100", "500", "1000", "5000+"), 3, "Histoire", Difficulty.HARD, explanation = "Les estimations des historiens varient, mais les chroniques espagnoles et les codex aztèques suggèrent que des milliers de prisonniers de guerre étaient sacrifiés chaque année lors de cérémonies religieuses."),
        Question(12788, "Quel légume était la principale récolte aztèque?", listOf("Maïs", "Haricot", "Courge", "Tomate"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le maïs était la base de l'alimentation aztèque, cultivé comme culture principale dans tout l'empire."),
        Question(12789, "En quelle année l'Empire aztèque a-t-il atteint son apogée?", listOf("1400", "1450", "1500", "1519"), 3, "Histoire", Difficulty.HARD, explanation = "1519 marque l'arrivée des conquistadors espagnols menés par Hernán Cortés, qui coïncide avec l'apogée de l'Empire aztèque sous le règne de Moctezuma II, juste avant sa chute."),
        Question(12790, "Quel était le système d'écriture aztèque?", listOf("Alphabétique", "Hiéroglyphes", "Syllabaire", "Logographique"), 3, "Histoire", Difficulty.HARD, explanation = "Le système d'écriture aztèque était logographique, utilisant des pictogrammes et des idéogrammes pour représenter des mots ou des concepts, sans alphabet phonétique complet."),
        Question(12791, "Combien d'états vassaux tributaires l'Empire aztèque avait-il?", listOf("20", "40", "60", "80+"), 3, "Histoire", Difficulty.HARD, explanation = "L'Empire aztèque, dirigé depuis Tenochtitlan, contrôlait une vaste zone de Mésoamérique via un système de tribut imposé à plus de 80 cités-États conquises, sans administration directe. Ces États vassaux devaient fournir régulièrement des biens précieux, des denrées et des victimes sacrificielles."),
        Question(12792, "Quel empereur aztèque a établi l'empire?", listOf("Montezuma I", "Itzcoatl", "Tenochtitlan", "Huitzilihuitl"), 1, "Histoire", Difficulty.HARD, explanation = "Itzcoatl, quatrième souverain mexica, a fondé la Triple Alliance en 1428 avec Texcoco et Tlacopan, posant ainsi les bases de l'empire aztèque."),
        Question(12793, "Quelle était la main-d'œuvre principale dans l'Empire aztèque?", listOf("Esclaves", "Tributaires", "Paysans libres", "Serfs"), 1, "Histoire", Difficulty.HARD, explanation = "Les Aztèques soumettaient les peuples conquis au versement d'un tribut en biens et en services, incluant des travailleurs pour les chantiers publics et l'agriculture."),
        Question(12794, "Combien de pyramides avait le temple Templo Mayor?", listOf("1", "2", "3", "5"), 1, "Histoire", Difficulty.HARD, explanation = "Le Templo Mayor, principal temple de la capitale aztèque Tenochtitlan, possédait deux pyramides jumelles dédiées aux dieux Huitzilopochtli et Tlaloc."),
        Question(12795, "Quel fut le dernier empereur aztèque?", listOf("Montezuma II", "Cuauhtemoc", "Axayacatl", "Moctezuma"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Cuauhtemoc fut le dernier empereur aztèque, capturé par les Espagnols en 1521 lors de la chute de Tenochtitlan, mettant fin à l'empire."),
        Question(12796, "En quelle année le temple Templo Mayor a-t-il été redéouvert?", listOf("1700", "1800", "1900", "1978"), 3, "Histoire", Difficulty.HARD, explanation = "Le Templo Mayor, le principal temple aztèque de Tenochtitlan, a été redécouvert en 1978 lors de travaux d'excavation pour le métro de Mexico, après des siècles d'enfouissement sous la ville moderne."),
        Question(12797, "Le xocolatl aztèque était préparé comment?", listOf("Sucré", "Amer épicé", "Laiteux", "Glacé"), 1, "Histoire", Difficulty.HARD, explanation = "Le xocolatl était une boisson à base de fèves de cacao, d'eau et d'épices comme le piment, sans sucre, d'où son goût amer et épicé."),
        Question(12798, "Combien de sous-empires composaient la Triple Alliance aztèque?", listOf("2", "3", "4", "5"), 1, "Histoire", Difficulty.HARD, explanation = "La Triple Alliance aztèque était composée de trois cités-États : Tenochtitlan, Texcoco et Tlacopan."),
        Question(12799, "Quel était le sport aztèque principal?", listOf("Jeu de balle", "Lutte", "Course", "Natation"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le jeu de balle, appelé tlachtli, était un rituel religieux et sportif central chez les Aztèques, souvent associé à des sacrifices humains."),

        // SPORT - E-SPORTS AVANCÉ
        Question(12800, "Quel tournoi de Dota 2 offre le plus grand prize pool?", listOf("International", "Majors", "Minors", "Regionals"), 0, "Sport", Difficulty.HARD, explanation = "The International est le championnat du monde annuel de Dota 2, organisé par Valve, dont le prize pool est principalement financé par les achats du Battle Pass, atteignant des records comme 40 millions de dollars en 2021."),
        Question(12801, "Combien de joueurs par équipe en League of Legends compétitif?", listOf("3", "5", "7", "10"), 1, "Sport", Difficulty.EASY, explanation = "En League of Legends compétitif, chaque équipe est composée de cinq joueurs, un par poste : top, jungle, mid, ADC et support."),
        Question(12802, "Quel joueur de Valorant a le taux d'headshot le plus élevé?", listOf("TenZ", "Yay", "Asuna", "Cned"), 1, "Sport", Difficulty.HARD, explanation = "Yay, joueur professionnel de Valorant, détient le record du plus haut taux de headshot en compétition, notamment grâce à son rôle de duelist et sa précision légendaire."),
        Question(12803, "En quelle année la première esports Olympics a-t-elle eu lieu?", listOf("2018", "2022", "2024", "2026"), 3, "Sport", Difficulty.HARD, explanation = "Le Comité International Olympique a officiellement lancé les Olympic Esports Games en 2026, marquant la première compétition esportive sous l'égide olympique."),
        Question(12804, "Quel est le plus grand tournoi de Counter-Strike?", listOf("ESL Pro League", "PGL Major", "IEM Katowice", "CS Masters"), 2, "Sport", Difficulty.HARD, explanation = "IEM Katowice est considéré comme le plus grand tournoi de Counter-Strike en raison de son prestige historique, de son immense dotation et de son atmosphère légendaire dans la Spodek Arena."),
        Question(12805, "Combien de millions de spectateurs les Worlds LoL 2022 ont-eux attiré?", listOf("50", "100", "300", "500"), 2, "Sport", Difficulty.HARD, explanation = "Les Worlds 2022 de League of Legends ont atteint un pic de plus de 5 millions de spectateurs simultanés, mais environ 300 millions de personnes uniques ont regardé l'événement au total, ce qui en fait l'un des tournois d'esport les plus regardés."),
        Question(12806, "Quel équipe a remporté le plus de titres LoL Worlds?", listOf("SKT T1", "Samsung", "Fnatic", "G2 Esports"), 0, "Sport", Difficulty.HARD, explanation = "SKT T1 a remporté le championnat du monde de League of Legends à quatre reprises (2013, 2015, 2016, 2023), un record inégalé dans l'histoire de la compétition."),
        Question(12807, "Quel est le plus haut salaire d'un joueur esports?", listOf("1 million", "5 millions", "10 millions", "20 millions"), 2, "Sport", Difficulty.HARD, explanation = "Le joueur d'esports le mieux payé, notamment dans des jeux comme Fortnite ou League of Legends, peut atteindre 10 millions de dollars annuels grâce aux contrats, sponsors et gains de tournois."),
        Question(12808, "Combien de prix Nobel Gaming Awards a-t-on décernés?", listOf("0", "1", "2", "5"), 0, "Sport", Difficulty.HARD, explanation = "Le Prix Nobel Gaming Awards n'existe pas. Aucun prix de ce nom n'a jamais été décerné, contrairement au vrai Prix Nobel."),
        Question(12809, "Quel est le tournoi esports avec le plus grand audience?", listOf("Worlds LoL", "International Dota", "IEM Katowice", "Fortnite World Cup"), 0, "Sport", Difficulty.HARD, explanation = "Les Worlds de League of Legends (LoL) sont le championnat du monde du jeu vidéo, attirant chaque année des dizaines de millions de spectateurs en ligne et en stade."),
        Question(12810, "Combien de pays participent aux Esports Olympics?", listOf("20", "50", "100", "150+"), 3, "Sport", Difficulty.HARD, explanation = "Les Esports Olympics ont réuni plus de 150 pays lors de leur première édition, reflétant la portée mondiale croissante du sport électronique."),
        Question(12811, "Quel est le plus grand casino d'esports du monde?", listOf("Las Vegas", "Dubaï", "Singapour", "Tokyo"), 1, "Sport", Difficulty.HARD, explanation = "Le plus grand casino d'esports du monde, le Dubai Esports & Gaming Festival, se trouve à Dubaï, aux Émirats arabes unis, attirant des joueurs et spectateurs du monde entier."),
        Question(12812, "En quelle année les esports sont devenus médaille aux Jeux Asiatiques?", listOf("2018", "2022", "2026", "2030"), 1, "Sport", Difficulty.HARD, explanation = "Les Jeux Asiatiques de 2022 à Hangzhou ont inclus les sports électroniques comme épreuve officielle, marquant une première dans l'histoire de cette compétition multisports."),
        Question(12813, "Quel est le meilleur joueur de Valorant de tous les temps?", listOf("TenZ", "Yay", "Mixwell", "Derke"), 0, "Sport", Difficulty.HARD, explanation = "TenZ est largement reconnu comme le meilleur joueur de Valorant pour ses performances dominantes en compétition, notamment son titre de MVP au Masters de Reykjavik 2021."),
        Question(12814, "Combien de prisepools les esports ont-elles distribuées en 2023?", listOf("500 millions", "1 milliard", "2 milliards", "5 milliards"), 1, "Sport", Difficulty.HARD, explanation = "En 2023, les compétitions d'esports ont distribué plus d'un milliard de dollars de prix cumulés, un record historique porté par la croissance des jeux comme Dota 2 et Fortnite."),
        Question(12815, "Quel joueur de LoL a le plus de titres Worlds?", listOf("Faker", "Score", "Pawn", "Duke"), 0, "Sport", Difficulty.HARD, explanation = "Faker, joueur sud-coréen de T1, détient le record avec quatre titres de champion du monde de League of Legends (2013, 2015, 2016, 2023)."),
        Question(12816, "Combien de millions de fans esports existent globalement?", listOf("100", "250", "500", "1000"), 3, "Sport", Difficulty.HARD, explanation = "Le nombre de fans d'esports dans le monde dépasse le milliard, soit environ 1000 millions, selon les estimations récentes de l'industrie."),
        Question(12817, "Quel tournoi de Dota 2 a le record de prize pool?", listOf("TI10", "TI9", "TI11", "TI12"), 1, "Sport", Difficulty.HARD, explanation = "TI9, ou The International 2019, détient le record du plus gros prize pool de l'histoire de Dota 2, atteignant plus de 34 millions de dollars grâce au financement participatif via le Battle Pass."),
        Question(12818, "Quel pays domine les esports par nombre de joueurs pro?", listOf("Corée du Sud", "Chine", "USA", "Suède"), 1, "Sport", Difficulty.HARD, explanation = "La Chine est le pays qui compte le plus grand nombre de joueurs professionnels d'esports au monde, grâce à une forte culture du jeu vidéo et à des investissements massifs dans l'industrie."),
        Question(12819, "En quelle année Twitch a-t-elle été acquise par Amazon?", listOf("2012", "2014", "2016", "2018"), 1, "Sport", Difficulty.HARD, explanation = "Amazon a acquis Twitch en 2014 pour 970 millions de dollars, renforçant ainsi sa présence dans le secteur du streaming de jeux vidéo."),

        // SCIENCE - NANOSCIENCE AVANCÉE
        Question(12820, "Quelle est la taille d'un nanomètre?", listOf("10^-6m", "10^-9m", "10^-12m", "10^-15m"), 1, "Science", Difficulty.MEDIUM, explanation = "Un nanomètre correspond à un milliardième de mètre, soit 10^-9 mètre, une unité utilisée pour mesurer des objets à l'échelle atomique et moléculaire."),
        Question(12821, "Combien d'atomes peuvent tenir sur la pointe d'une aiguille?", listOf("Millions", "Milliards", "Trillions", "Quadrillions"), 2, "Science", Difficulty.HARD, explanation = "La pointe d'une aiguille, bien que minuscule, contient des milliards d'atomes en raison de leur taille nanométrique. Un atome mesure environ 0,1 nanomètre, permettant d'en aligner des millions sur une surface de quelques micromètres carrés."),
        Question(12822, "Quel est l'application principale des nanotubes de carbone?", listOf("Électronique", "Batterie", "Tissu", "Médicine"), 1, "Science", Difficulty.HARD, explanation = "Les nanotubes de carbone sont utilisés dans les batteries pour améliorer la conductivité électrique et la capacité de stockage d'énergie, notamment dans les batteries lithium-ion."),
        Question(12823, "Combien de fois plus fort un nanotube de carbone que l'acier?", listOf("5x", "10x", "50x", "100x"), 3, "Science", Difficulty.HARD, explanation = "Les nanotubes de carbone possèdent une structure hexagonale en feuillet d'atomes de carbone, leur conférant une résistance à la traction environ 100 fois supérieure à celle de l'acier, tout en étant beaucoup plus légers."),
        Question(12824, "Quel est le plus petit transistor jamais créé?", listOf("3 nm", "5 nm", "7 nm", "1 nm"), 3, "Science", Difficulty.HARD, explanation = "En 2016, des chercheurs du Laboratoire national de Lawrence Berkeley ont fabriqué un transistor avec une grille de seulement 1 nanomètre, repoussant les limites de la miniaturisation des composants électroniques."),
        Question(12825, "Quelle technique permet de voir les atomes?", listOf("Microscope optique", "Microscope électronique", "Microscope à force atomique", "Loupe"), 2, "Science", Difficulty.HARD, explanation = "Le microscope à force atomique utilise une sonde qui effleure la surface d'un échantillon pour cartographier ses atomes, contrairement aux microscopes optiques limités par la longueur d'onde de la lumière."),
        Question(12826, "Combien d'atomes de carbonne ont le graphène?", listOf("1 par nanomètre carré", "Millions", "Un seul", "Infini"), 0, "Science", Difficulty.HARD, explanation = "Le graphène est un matériau bidimensionnel composé d'une seule couche d'atomes de carbone. Sa structure en nid d'abeille contient environ un atome par nanomètre carré."),
        Question(12827, "Quelle est la conductivité thermique du graphène?", listOf("1x", "10x", "100x", "5000x"), 3, "Science", Difficulty.HARD, explanation = "Le graphène possède une conductivité thermique exceptionnelle, environ 5000 W/mK, grâce à la structure en nid d'abeille de ses atomes de carbone qui permet une transmission très efficace de la chaleur par les vibrations du réseau."),
        Question(12828, "Quel nanomatériau est transparent et conducteur?", listOf("Graphène", "Oxyde de graphène", "Nanotube", "Nanoparticule d'or"), 1, "Science", Difficulty.HARD, explanation = "L'oxyde de graphène est un dérivé du graphène qui conserve sa conductivité électrique tout en devenant transparent, ce qui le rend utile pour les écrans tactiles et les cellules solaires."),
        Question(12829, "Combien de couches a une nanofeuille?", listOf("1", "10", "100", "1000"), 0, "Science", Difficulty.HARD, explanation = "Une nanofeuille est un matériau bidimensionnel dont l'épaisseur est de l'ordre du nanomètre, ce qui correspond à une seule couche atomique ou moléculaire."),
        Question(12830, "Quelle est la surface spécifique du graphène?", listOf("100 m2/g", "1000 m2/g", "2600 m2/g", "10000 m2/g"), 2, "Science", Difficulty.HARD, explanation = "Le graphène, une seule couche d'atomes de carbone, possède une surface spécifique théorique de 2630 m²/g, car chaque atome est exposé. Cette valeur record vient de sa structure bidimensionnelle extrêmement fine."),
        Question(12831, "Quel est le diamètre d'un nanotube de carbone?", listOf("1 nm", "10 nm", "100 nm", "1000 nm"), 1, "Science", Difficulty.HARD, explanation = "Un nanotube de carbone a typiquement un diamètre d'environ 10 nanomètres, soit 10 milliardièmes de mètre, ce qui le rend 100 000 fois plus fin qu'un cheveu humain."),
        Question(12832, "Quelle propriété quantique les nanoparticules exploitent-elles?", listOf("Confinement quantique", "Intrication", "Superposition", "Décohérence"), 0, "Science", Difficulty.HARD, explanation = "Le confinement quantique se produit lorsque la taille d'une particule est réduite à l'échelle nanométrique, modifiant ses propriétés électroniques et optiques par rapport au matériau massif."),
        Question(12833, "Combien de couches le graphène monocouche a-t-elle?", listOf("1", "2", "3", "10"), 0, "Science", Difficulty.EASY, explanation = "Le graphène monocouche est une forme de carbone constituée d'une seule couche d'atomes arrangés en réseau hexagonal, d'où son nom."),
        Question(12834, "Quel est l'application médicale des nanoparticules d'or?", listOf("Thérapie génique", "Imagerie", "Libération de médicaments", "Détection de cancer"), 3, "Science", Difficulty.HARD, explanation = "Les nanoparticules d'or s'accumulent dans les tumeurs et réfléchissent la lumière, permettant une imagerie plus précise pour détecter les cancers à un stade précoce."),
        Question(12835, "Quelle est la résistance mécanique du graphène?", listOf("1 GPa", "10 GPa", "130 GPa", "1000 GPa"), 2, "Science", Difficulty.HARD, explanation = "Le graphène est le matériau le plus résistant jamais testé, avec une résistance à la traction d'environ 130 GPa, soit plus de 100 fois celle de l'acier."),
        Question(12836, "Combien de transistors tendraient dans 1 micromètre carré?", listOf("Millions", "Milliards", "Trillions", "Quadrillions"), 2, "Science", Difficulty.HARD, explanation = "Les transistors modernes mesurent quelques nanomètres, permettant d'en placer des milliards sur une puce. Un micromètre carré peut donc en contenir des trillions."),
        Question(12837, "Quel est le coût actuel du graphène par gramme?", listOf("0,001€", "0,1€", "1€", "100€"), 2, "Science", Difficulty.HARD, explanation = "Le graphène est un matériau extrêmement coûteux à produire en raison des procédés complexes nécessaires, mais son prix a chuté grâce aux progrès de fabrication, atteignant environ 1€ par gramme pour certaines qualités."),
        Question(12838, "Combien d'années avant que la nanoscience atteigne la production de masse?", listOf("2", "5", "10", "20"), 2, "Science", Difficulty.HARD, explanation = "La nanoscience est encore en phase de recherche et développement, et les experts estiment qu'il faudra environ 10 ans avant que ses applications atteignent une production industrielle à grande échelle."),
        Question(12839, "Quelle est la conductivité électrique du graphène?", listOf("Bonne", "Excellente", "Supérieur au cuivre", "Supérieur à l'argent"), 2, "Science", Difficulty.HARD, explanation = "Le graphène possède une mobilité électronique exceptionnellement élevée, ce qui lui confère une conductivité électrique supérieure à celle du cuivre, le métal conducteur de référence."),

        // GEOGRAPHIE - ILES DU PACIFIQUE
        Question(12840, "Combien d'îles la Polynésie française compte-t-elle?", listOf("50", "100", "150", "200"), 2, "Géographie", Difficulty.HARD, explanation = "La Polynésie française est un archipel composé de 118 îles réparties en cinq groupes, mais le nombre total d'îles et d'îlots est souvent estimé à environ 150."),
        Question(12841, "Quelle est la plus grande île de la Polynésie?", listOf("Tahiti", "Bora Bora", "Marquises", "Tuamotu"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Tahiti est la plus grande île de la Polynésie française, avec une superficie d'environ 1 045 km², et elle constitue le centre économique et culturel de cet archipel du Pacifique."),
        Question(12842, "Combien d'îles l'archipel du Samoa compte-t-il?", listOf("5", "9", "15", "20"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel du Samoa est politiquement divisé en deux entités : les Samoa (indépendantes) et les Samoa américaines. Au total, il compte neuf îles habitées."),
        Question(12843, "Quel est le point culminant de Hawaï?", listOf("Mauna Kea", "Mauna Loa", "Haleakala", "Kohala"), 0, "Géographie", Difficulty.HARD, explanation = "Le Mauna Kea, volcan endormi, culmine à 4 207 mètres, ce qui en fait le plus haut sommet d'Hawaï, bien que sa base repose sur le plancher océanique."),
        Question(12844, "Combien d'îles les Fidji compte-elles?", listOf("100", "200", "330", "500"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel des Fidji est composé d'environ 330 îles, dont seulement un tiers sont habitées."),
        Question(12845, "Quel est le plus petit État du Pacifique?", listOf("Nauru", "Tuvalu", "Palaos", "Kiribati"), 0, "Géographie", Difficulty.HARD, explanation = "Nauru est une île de 21 km², ce qui en fait le plus petit État insulaire du Pacifique et le troisième plus petit pays du monde après le Vatican et Monaco."),
        Question(12846, "Combien d'îles la Micronésie compte-t-elle?", listOf("500", "1000", "2000", "5000"), 1, "Géographie", Difficulty.HARD, explanation = "La Micronésie est une région de l'océan Pacifique composée de plus de 2 000 îles, mais le nom du pays fait référence à environ 600 îles principales, dont seulement 65 sont habitées. Le chiffre de 1 000 est souvent cité comme une approximation des îles de l'archipel."),
        Question(12847, "Quel est le plus grand lagon du Pacifique?", listOf("Rangiroa", "Fakarava", "Raroia", "Hao"), 1, "Géographie", Difficulty.HARD, explanation = "Le lagon de Fakarava, situé dans l'archipel des Tuamotu en Polynésie française, est le deuxième plus grand lagon du monde après celui de Rangiroa, mais il est le plus vaste du Pacifique en termes de superficie."),
        Question(12848, "Combien d'atolls Kiribati compte-t-elle?", listOf("30", "50", "100", "150"), 2, "Géographie", Difficulty.HARD, explanation = "Kiribati est un pays insulaire du Pacifique composé de 33 atolls et îles coralliennes, mais le nombre total d'atolls dans son territoire est estimé à environ 100 en incluant les îlots et récifs."),
        Question(12849, "Quel est le plus haut point des îles Salomon?", listOf("1000m", "1500m", "2000m", "2500m"), 3, "Géographie", Difficulty.HARD, explanation = "Le plus haut point des îles Salomon est le mont Popomanaseu, culminant à environ 2 500 mètres d'altitude sur l'île de Guadalcanal."),
        Question(12850, "Combien de volcanoes actifs Vanuatu a-t-elle?", listOf("5", "10", "15", "20"), 2, "Géographie", Difficulty.HARD, explanation = "Vanuatu se trouve sur la ceinture de feu du Pacifique, ce qui explique sa forte activité volcanique avec 15 volcans actifs recensés."),
        Question(12851, "Quel est le plus grand atoll des Maldives?", listOf("Malé", "Baa", "Vaavu", "Addu"), 1, "Géographie", Difficulty.HARD, explanation = "L'atoll de Baa est le plus grand des Maldives, couvrant environ 1 200 km². Il est célèbre pour sa biodiversité marine et abrite la réserve de biosphère de l'UNESCO."),
        Question(12852, "Combien d'îles Tonga compte-t-elle?", listOf("100", "150", "200", "300"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel des Tonga, dans le Pacifique Sud, est composé d'environ 200 îles, dont seulement une trentaine sont habitées."),
        Question(12853, "Quelle est la profondeur de la Fosse des Mariannes?", listOf("7000m", "9000m", "11000m", "13000m"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La Fosse des Mariannes, point le plus profond des océans, atteint environ 11 000 mètres de profondeur, soit plus que la hauteur de l'Everest."),
        Question(12854, "Combien d'îles l'archipel du Cook compte-t-il?", listOf("10", "15", "20", "25"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel des îles Cook, État autonome en libre association avec la Nouvelle-Zélande, est composé de 15 îles principales et 5 atolls inhabités, soit un total de 20 îles."),
        Question(12855, "Quel est le plus grand lagon du monde?", listOf("Bora Bora", "Rangiroa", "Fakarava", "Raiatea"), 1, "Géographie", Difficulty.HARD, explanation = "Le lagon de Rangiroa, dans l'archipel des Tuamotu en Polynésie française, est le plus grand du monde avec une superficie de 1 446 km²."),
        Question(12856, "Combien d'îles Samoa Américaines compte-elle?", listOf("3", "5", "7", "10"), 1, "Géographie", Difficulty.HARD, explanation = "Les Samoa américaines sont composées de cinq îles principales (Tutuila, Aunu'u, Ofu, Olosega et Ta'ū) et deux atolls de corail."),
        Question(12857, "Quel est l'atoll le plus peuplé du monde?", listOf("Malé", "Tarawa", "Majuro", "Funafuti"), 1, "Géographie", Difficulty.HARD, explanation = "Tarawa, atoll des Kiribati, concentre plus de la moitié de la population du pays sur ses îlots, ce qui en fait l'atoll le plus densément peuplé au monde."),
        Question(12858, "Combien de volcans Bougainville compte-t-elle?", listOf("2", "4", "6", "10"), 1, "Géographie", Difficulty.HARD, explanation = "L'île de Bougainville, en Papouasie-Nouvelle-Guinée, possède quatre volcans principaux, dont le mont Balbi et le mont Bagana, ce dernier étant l'un des plus actifs du pays."),
        Question(12859, "Quel est le plus large atoll du monde?", listOf("Malé", "Kwajalein", "Fakarava", "Chagos"), 2, "Géographie", Difficulty.HARD, explanation = "Fakarava, dans l'archipel des Tuamotu en Polynésie française, est le deuxième plus grand atoll du monde par sa superficie totale, mais il possède le plus large lagon."),

        // NATURE - MIGRATIONS ANIMALES
        Question(12860, "Quelle est la plus longue migration animale?", listOf("Grue", "Sterne arctique", "Baleine grise", "Monarque"), 1, "Nature", Difficulty.HARD, explanation = "La sterne arctique parcourt environ 70 000 kilomètres par an entre l'Arctique et l'Antarctique, ce qui en fait la plus longue migration animale connue."),
        Question(12861, "Combien de kilomètres migre la sterne arctique annuellement?", listOf("40000", "70000", "90000", "120000"), 2, "Nature", Difficulty.HARD, explanation = "La sterne arctique effectue la plus longue migration de tous les animaux, parcourant environ 90 000 kilomètres par an entre ses sites de reproduction dans l'Arctique et ses zones d'hivernage en Antarctique."),
        Question(12862, "Quel animal migre le plus haut en altitude?", listOf("Aigle royal", "Oie bernache", "Vautour de Rüppell", "Grue"), 2, "Nature", Difficulty.HARD, explanation = "Le vautour de Rüppell peut voler à plus de 11 000 mètres d'altitude, ce qui en fait l'animal volant le plus haut jamais enregistré."),
        Question(12863, "Combien de monarques migrent au Mexique chaque année?", listOf("100 millions", "500 millions", "1 milliard", "2 milliards"), 2, "Nature", Difficulty.HARD, explanation = "Chaque année, jusqu'à un milliard de papillons monarques migrent du Canada et des États-Unis vers les forêts du Mexique pour hiverner."),
        Question(12864, "Quel est le plus long voyage d'un cétacé migrant?", listOf("5000 km", "10000 km", "15000 km", "20000 km"), 3, "Nature", Difficulty.HARD, explanation = "La baleine grise détient le record avec des migrations allant jusqu'à 20 000 km, parcourant l'océan Pacifique entre ses zones d'alimentation arctiques et ses lagons de reproduction mexicains."),
        Question(12865, "En combien de jours les baleines grises migrent-elles?", listOf("30", "60", "90", "180"), 2, "Nature", Difficulty.HARD, explanation = "Les baleines grises effectuent l'une des plus longues migrations du règne animal, parcourant jusqu'à 10 000 kilomètres aller-retour entre leurs zones d'alimentation arctiques et leurs lagunes de reproduction mexicaines, un voyage qui dure environ 90 jours."),
        Question(12866, "Quelle est la capacité sensorielle des oiseaux migrateurs?", listOf("Vue", "Géomagnétisme", "Odorat", "Tous"), 3, "Nature", Difficulty.HARD, explanation = "Les oiseaux migrateurs utilisent plusieurs sens pour s'orienter, notamment la vue, l'odorat et la perception du champ magnétique terrestre. Aucun sens unique n'est exclusif, ils combinent tous ces moyens selon les espèces et les conditions."),
        Question(12867, "Combien d'espèces de poissons migrent annuellement?", listOf("100", "500", "1000", "2000"), 2, "Nature", Difficulty.HARD, explanation = "Environ 1000 espèces de poissons effectuent des migrations annuelles, principalement pour se reproduire ou se nourrir, comme les saumons ou les anguilles."),
        Question(12868, "Quel est le plus haut record de migration de nuit?", listOf("5000m", "7000m", "9000m", "11000m"), 2, "Nature", Difficulty.HARD, explanation = "Certains oiseaux, comme les bécasseaux, peuvent voler à plus de 9 000 mètres d'altitude la nuit pour franchir des chaînes de montagnes ou éviter des prédateurs."),
        Question(12869, "Combien de tortues marines migrent annuellement?", listOf("Millions", "Dizaines de millions", "Centaines de millions", "Milliards"), 2, "Nature", Difficulty.HARD, explanation = "Les tortues marines effectuent des migrations massives à l'échelle mondiale, avec des centaines de millions d'individus se déplaçant chaque année entre les zones d'alimentation et de reproduction."),
        Question(12870, "Quel animal a la plus courte migration?", listOf("Papillon monarque", "Caribou", "Souris d'herbe", "Zooplancton"), 3, "Nature", Difficulty.HARD, explanation = "Le zooplancton effectue des migrations verticales quotidiennes dans l'océan, montant la nuit vers la surface et redescendant le jour, ce qui en fait la plus courte migration connue."),
        Question(12871, "En combien de semaines la grue migre-t-elle?", listOf("2", "4", "6", "8"), 2, "Nature", Difficulty.HARD, explanation = "La migration de la grue cendrée entre ses zones de reproduction et d'hivernage dure environ six semaines, incluant des escales pour se reposer et se nourrir."),
        Question(12872, "Quel est le record de distance parsauterioe sans escale?", listOf("2000 km", "4000 km", "6000 km", "8000 km"), 3, "Nature", Difficulty.HARD, explanation = "Le martinet noir détient le record de vol sans escale, parcourant jusqu'à 10 mois d'affilée sans se poser."),
        Question(12873, "Combien de générations de monarques effectuent la migration?", listOf("1", "2", "3", "4"), 3, "Nature", Difficulty.HARD, explanation = "Les monarques effectuent une migration annuelle sur plusieurs générations : la première génération migre vers le nord au printemps, la deuxième et la troisième se reproduisent en été, et la quatrième génération migre vers le sud à l'automne."),
        Question(12874, "Quel est le plus long trajet migratoire des poissons?", listOf("5000 km", "10000 km", "15000 km", "20000 km"), 2, "Nature", Difficulty.HARD, explanation = "Le saumon rouge parcourt jusqu'à 15 000 km depuis l'océan Pacifique jusqu'à ses frayères en eau douce, ce qui en fait la plus longue migration chez les poissons."),
        Question(12875, "En quelle saison les caribous migrent-ils?", listOf("Automne", "Hiver", "Printemps", "Été"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les caribous migrent à l'automne pour rejoindre leurs aires d'hivernage plus au sud, où la nourriture est plus accessible sous la neige."),
        Question(12876, "Quel est le principal carburant migratoire des oiseaux?", listOf("Protéine", "Graisse", "Carbohydrates", "Minéraux"), 1, "Nature", Difficulty.HARD, explanation = "La graisse est le principal carburant des oiseaux migrateurs car elle fournit une grande quantité d'énergie par gramme, essentielle pour les longs vols sans ravitaillement."),
        Question(12877, "Combien de kilomètres le gnou migre-t-il?", listOf("5000", "10000", "15000", "20000"), 1, "Nature", Difficulty.HARD, explanation = "Chaque année, les gnous parcourent environ 10 000 kilomètres lors de leur grande migration à travers le Serengeti et le Masai Mara, suivant les pluies pour trouver de l'herbe fraîche."),
        Question(12878, "Quel est le plus court intervalle migratoire?", listOf("Jours", "Semaines", "Heures", "Minutes"), 2, "Nature", Difficulty.HARD, explanation = "Le plus court intervalle migratoire est de quelques heures, observé chez certaines espèces de zooplancton qui effectuent des migrations verticales quotidiennes dans l'océan."),
        Question(12879, "Combien de fois le caribou change-t-il d'habitat?", listOf("Une fois", "Deux fois", "Quatre fois", "Huit fois"), 2, "Nature", Difficulty.HARD, explanation = "Le caribou change d'habitat quatre fois par an pour suivre les saisons et les ressources alimentaires. Il se déplace entre les zones de mise bas, d'estivage, de rut et d'hivernage."),

        // TECHNOLOGIE - RÉALITÉ VIRTUELLE
        Question(12880, "En quelle année Oculus a-t-il été lancé?", listOf("2010", "2012", "2014", "2016"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Oculus a été lancé en 2012 via une campagne Kickstarter pour son premier casque de réalité virtuelle, l'Oculus Rift, marquant le début de la démocratisation de cette technologie."),
        Question(12881, "Quel est le prix du Meta Quest 3?", listOf("300€", "500€", "800€", "1200€"), 1, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 a été lancé en 2023 à un prix de départ de 500€ pour le modèle de base, positionné comme un casque de réalité mixte grand public."),
        Question(12882, "Combien de pixels par œil le Meta Quest 3 a-t-il?", listOf("1440", "1920", "2560", "3840"), 2, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 offre une résolution de 2560 x 2560 pixels par œil, soit une amélioration significative par rapport au Quest 2, permettant une image plus nette et immersive."),
        Question(12883, "Quel est le taux de rafraîchissement standard en VR?", listOf("30 Hz", "60 Hz", "90 Hz", "120 Hz"), 2, "Technologie", Difficulty.HARD, explanation = "Le taux de rafraîchissement standard en réalité virtuelle est de 90 Hz pour éviter la nausée et offrir une expérience fluide, car en dessous de ce seuil, le décalage visuel perturbe l'immersion."),
        Question(12884, "Quelle est la latence acceptable en VR?", listOf("50ms", "20ms", "10ms", "5ms"), 2, "Technologie", Difficulty.HARD, explanation = "En VR, une latence inférieure à 20 ms est nécessaire pour éviter la nausée, et 10 ms est considérée comme le seuil optimal pour une immersion fluide et réaliste."),
        Question(12885, "Combien d'utilisateurs VR actifs existaient en 2023?", listOf("50 millions", "100 millions", "200 millions", "300 millions"), 2, "Technologie", Difficulty.HARD, explanation = "En 2023, le nombre d'utilisateurs actifs de réalité virtuelle a atteint environ 200 millions, porté par la démocratisation des casques abordables et l'essor des applications grand public comme les jeux et la formation."),
        Question(12886, "Quel est le casque VR le plus vendu?", listOf("HTC Vive", "Meta Quest", "PlayStation VR", "Valve Index"), 1, "Technologie", Difficulty.MEDIUM, explanation = "Le Meta Quest (anciennement Oculus Quest) de Meta est le casque VR le plus vendu grâce à son rapport qualité-prix et son fonctionnement autonome, sans besoin d’un PC."),
        Question(12887, "En quelle année PlayStation VR a-t-il été lancé?", listOf("2014", "2015", "2016", "2017"), 2, "Technologie", Difficulty.MEDIUM, explanation = "Le PlayStation VR, le casque de réalité virtuelle de Sony, a été commercialisé en octobre 2016, en même temps que la PlayStation 4 Pro."),
        Question(12888, "Quel est l'angle de vision du Meta Quest 3?", listOf("90°", "100°", "110°", "120°"), 2, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 offre un champ de vision de 110 degrés, soit une amélioration par rapport aux 100 degrés du Quest 2, grâce à ses nouvelles optiques en forme de lentille pancake."),
        Question(12889, "Combien de capteurs le Meta Quest 3 possède-t-il?", listOf("5", "8", "10", "15"), 2, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 intègre 10 capteurs, combinant des caméras de suivi, des capteurs de profondeur et des accéléromètres pour une expérience de réalité mixte immersive."),
        Question(12890, "Quelle est la limite de distance pour les contrôleurs VR?", listOf("5m", "10m", "20m", "30m"), 2, "Technologie", Difficulty.HARD, explanation = "Les contrôleurs VR utilisent des capteurs infrarouges ou des caméras, dont la portée est généralement limitée à environ 20 mètres pour garantir une détection précise des mouvements."),
        Question(12891, "Quel est le poids du Meta Quest 3?", listOf("400g", "500g", "600g", "700g"), 1, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 pèse environ 500 grammes, un équilibre entre confort et performance pour un casque de réalité mixte autonome."),
        Question(12892, "Combien d'heures l'autonomie batterie du Quest 3?", listOf("2h", "3h", "5h", "8h"), 1, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 offre une autonomie d'environ 2 à 3 heures en utilisation intensive, selon les applications et les réglages."),
        Question(12893, "Quel est le résolution 4K?", listOf("3840x2160", "2560x1440", "1920x1080", "1280x720"), 0, "Technologie", Difficulty.EASY, explanation = "La résolution 4K, aussi appelée Ultra HD, correspond à 3840 pixels de largeur sur 2160 pixels de hauteur, soit quatre fois la définition du Full HD (1920x1080)."),
        Question(12894, "Combien de caméras le Meta Quest 3 possède-t-il?", listOf("4", "6", "8", "10"), 2, "Technologie", Difficulty.HARD, explanation = "Le Meta Quest 3 est équipé de deux caméras RV pour la réalité mixte, de quatre caméras de suivi, et de deux caméras de profondeur, totalisant huit capteurs."),
        Question(12895, "Quelle est la température idéale pour la VR?", listOf("15°C", "20°C", "25°C", "30°C"), 1, "Technologie", Difficulty.HARD, explanation = "Une température ambiante de 20°C est recommandée pour la réalité virtuelle afin d'éviter la surchauffe du casque et l'inconfort du joueur pendant l'effort."),
        Question(12896, "Quel est le taux d'adoption VR grand public?", listOf("5%", "10%", "20%", "40%"), 1, "Technologie", Difficulty.HARD, explanation = "En 2023, environ 10% des foyers américains possédaient un casque de réalité virtuelle, selon les données du marché. Ce taux reflète une adoption encore limitée, freinée par le coût et le manque de contenus."),
        Question(12897, "Combien de jeux VR existaient en 2023?", listOf("1000", "3000", "5000", "10000"), 3, "Technologie", Difficulty.HARD, explanation = "En 2023, le catalogue de jeux compatibles avec la réalité virtuelle dépassait les 10 000 titres sur les principales plateformes comme SteamVR et l'Oculus Store."),
        Question(12898, "Quel est le prix du Valve Index?", listOf("500€", "800€", "1100€", "1500€"), 2, "Technologie", Difficulty.HARD, explanation = "Le Valve Index, un casque de réalité virtuelle haut de gamme de Valve, était proposé à 1100€ lors de son lancement en 2019, incluant les contrôleurs et les stations de base."),
        Question(12899, "Combien de mégahertz le processeur du Quest 3?", listOf("2000", "3000", "4000", "5000"), 2, "Technologie", Difficulty.HARD, explanation = "Le processeur du Meta Quest 3, le Snapdragon XR2 Gen 2, fonctionne à une fréquence maximale de 4 GHz, soit 4000 MHz."),

        // HISTOIRE - GUERRE DE SÉCESSION
        Question(12900, "En quelle année la Guerre de Sécession a-t-elle commencé?", listOf("1860", "1861", "1862", "1863"), 1, "Histoire", Difficulty.EASY, explanation = "La guerre de Sécession a débuté en 1861 suite à l'élection d'Abraham Lincoln et à la sécession des États du Sud. Les hostilités ont commencé avec l'attaque confédérée sur Fort Sumter en avril 1861."),
        Question(12901, "Combien d'États confédérés ont participé à la Guerre de Sécession?", listOf("7", "11", "15", "20"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Onze États esclavagistes du Sud ont fait sécession de l'Union entre 1860 et 1861 pour former les États confédérés d'Amérique, déclenchant la Guerre de Sécession."),
        Question(12902, "Quel général confédéré a remporté le plus de victoires?", listOf("Grant", "Lee", "Jackson", "Beauregard"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Thomas Jonathan « Stonewall » Jackson est considéré comme l'un des plus brillants stratèges de la guerre de Sécession, remportant des batailles décisives comme celle de Chancellorsville."),
        Question(12903, "En quelle année la Guerre de Sécession a-t-elle pris fin?", listOf("1864", "1865", "1866", "1867"), 1, "Histoire", Difficulty.EASY, explanation = "La guerre de Sécession s'est achevée en 1865 avec la reddition du général confédéré Robert E. Lee à Appomattox, mettant fin à quatre années de conflit entre les États du Nord et du Sud."),
        Question(12904, "Combien de soldats sont morts pendant la Guerre de Sécession?", listOf("200000", "400000", "600000", "800000"), 2, "Histoire", Difficulty.HARD, explanation = "La Guerre de Sécession américaine (1861-1865) fut l'un des conflits les plus meurtriers de l'histoire des États-Unis, avec environ 600 000 soldats morts au combat ou des suites de maladies."),
        Question(12905, "Quel était le président de la Confédération?", listOf("Abraham Lincoln", "Jefferson Davis", "Andrew Johnson", "James Buchanan"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Jefferson Davis fut le président des États confédérés d'Amérique, de 1861 à 1865, durant la guerre de Sécession."),
        Question(12906, "Quelle bataille a tourné le cours de la guerre?", listOf("Gettysburg", "Antietam", "Shiloh", "Fort Sumter"), 0, "Histoire", Difficulty.HARD, explanation = "La bataille de Gettysburg, en juillet 1863, marque un tournant décisif de la guerre de Sécession en stoppant l'invasion nordiste du territoire nord-américain par les Confédérés."),
        Question(12907, "Combien de batailles majeures la Guerre de Sécession a-t-elle eu?", listOf("10", "30", "50", "100"), 2, "Histoire", Difficulty.HARD, explanation = "La Guerre de Sécession américaine (1861-1865) a compté environ 50 batailles majeures, selon les historiens, incluant des affrontements comme Gettysburg et Antietam."),
        Question(12908, "Quel général de l'Union a remporté plus de batailles?", listOf("Grant", "Sherman", "Meade", "Burnside"), 1, "Histoire", Difficulty.HARD, explanation = "William Tecumseh Sherman est connu pour sa campagne dévastatrice à travers la Géorgie et les Carolines, remportant des victoires clés comme la prise d'Atlanta."),
        Question(12909, "En quelle année la Proclamation d'Émancipation a-t-elle été signée?", listOf("1861", "1862", "1863", "1864"), 2, "Histoire", Difficulty.HARD, explanation = "Signée par Abraham Lincoln le 1er janvier 1863, cette proclamation déclarait libres les esclaves des États confédérés pendant la guerre de Sécession."),
        Question(12910, "Combien d'esclaves la Proclamation d'Émancipation a-t-elle libérés?", listOf("1 million", "3 millions", "5 millions", "7 millions"), 1, "Histoire", Difficulty.HARD, explanation = "La Proclamation d'Émancipation, décrétée par Abraham Lincoln en 1863, ne s'appliquait qu'aux États confédérés en rébellion, libérant environ 3 millions d'esclaves sur les 4 millions que comptaient les États-Unis."),
        Question(12911, "Quel fort a été attaqué en premier par les confédérés?", listOf("Fort Sumter", "Fort Pickens", "Fort Jefferson", "Fort Jefferson"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le Fort Sumter, situé dans le port de Charleston en Caroline du Sud, fut bombardé par les forces confédérées le 12 avril 1861, marquant le début de la guerre de Sécession."),
        Question(12912, "En quelle année la Reconstruction du Sud a-t-elle commencé?", listOf("1863", "1865", "1867", "1870"), 1, "Histoire", Difficulty.HARD, explanation = "La Reconstruction du Sud a commencé en 1865, juste après la fin de la guerre de Sécession, visant à réintégrer les États confédérés et à gérer les droits des anciens esclaves."),
        Question(12913, "Combien d'États du Sud avaient aboli l'esclavage à la fin de la guerre?", listOf("0", "5", "10", "15"), 0, "Histoire", Difficulty.HARD, explanation = "La guerre de Sécession s'est achevée sans qu'aucun État du Sud n'ait volontairement aboli l'esclavage ; l'abolition a été imposée par le 13e amendement en 1865."),
        Question(12914, "Quel général confédéré a continué à combattre le plus longtemps?", listOf("Lee", "Joseph Johnston", "Hood", "Longstreet"), 1, "Histoire", Difficulty.HARD, explanation = "Joseph Johnston commanda la dernière armée confédérée encore en campagne, se rendant à Sherman le 26 avril 1865, soit près de deux semaines après la capitulation de Lee."),
        Question(12915, "Combien de régiments entièrement noirs ont participé à la guerre?", listOf("10", "50", "100", "200"), 2, "Histoire", Difficulty.HARD, explanation = "Pendant la guerre de Sécession, environ 100 régiments entièrement noirs, appelés United States Colored Troops, ont combattu pour l'Union."),
        Question(12916, "En quelle année le 13ème Amendement a-t-il été ratifié?", listOf("1865", "1866", "1867", "1868"), 0, "Histoire", Difficulty.HARD, explanation = "Le 13e Amendement, abolissant l'esclavage aux États-Unis, a été ratifié en 1865, après la guerre de Sécession et l'adoption par le Congrès en janvier de la même année."),
